insert into public.questions (id, subject, origin, stem, options, topic_ids, difficulty, tags, group_id, display_order, source_label, source_url, exam_year, exam_session, source_question_number, source_pdf_page, style_reference, theory_sources, verified_at, needs_manual_media_review) values
  ('l21-official-114-01', 'L21', 'official', '某電商企業希望利用自然語言處理（NLP）技術，分析顧客在社群平 台與商品評論中的文字內容，以即時掌握顧客對產品的滿意度變化。 若採用情感分析（Sentiment Analysis）模型，其主要目的為何？', '{"A":"預測顧客使用的語言風格與語氣","B":"判斷文本中所表達的情感傾向","C":"將顧客留言自動翻譯成企業內部指定語言","D":"產生顧客評論的自動化摘要內容"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 1, 'iPAS 114年第2梯次中級 L21 公告試題，第1題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 1, 1, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-02', 'L21', 'official', '某跨國金融科技公司導入Transformer 架構開發多語客服系統，以提 升長篇金融文件的自動翻譯品質。下列何者為該模型能顯著改善翻譯 準確度的主要原因？', '{"A":"透過自注意力機制（Self-Attention Mechanism）捕捉長距離語 境依賴關係","B":"透過卷積運算（Convolution Operation）加速訓練過程","C":"透過強化學習（Reinforcement Learning）自動調整語句生成策 略","D":"透過資料增強（Data Augmentation）平衡多語語料比例"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 2, 'iPAS 114年第2梯次中級 L21 公告試題，第2題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 2, 1, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-03', 'L21', 'official', '某企業計畫應用BERT（Bidirectional Encoder Representations from Transformers）模型分析大量顧客意見，以強化客服自動回覆 系統。在BERT 的預訓練過程中，「遮罩語言模型（Masked Language Model, MLM）」的主要訓練策略為何？', '{"A":"依序遮罩句尾詞語，讓模型從左到右逐步生成完整句子","B":"隨機遮罩部分詞語，並讓模型根據雙向上下文（Bidirectional Context）預測被遮罩的詞","C":"透過對抗訓練（Adversarial Training）生成語意相似的擾動樣 本以提升泛化性","D":"以未遮罩的詞為條件，使用解碼器（Decoder）結構重建整句內容"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 3, 'iPAS 114年第2梯次中級 L21 公告試題，第3題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 3, 1, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-04', 'L21', 'official', '在詞向量（Word Embedding）訓練方法中，GloVe（Global Vectors for Word Representation）與Word2Vec 的主要差異為何？', '{"A":"Word2Vec 以詞頻權重訓練詞向量，而GloVe 以隨機初始化向量進 行學習","B":"Word2Vec 以全局統計矩陣為基礎，而GloVe 採用神經網路進行上 下文預測","C":"Word2Vec 為基於預測的模型，而GloVe 為基於共現統計的模型","D":"Word2Vec 僅能用於靜態文本語料，而GloVe 可應用於即時語料更新"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 4, 'iPAS 114年第2梯次中級 L21 公告試題，第4題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 4, 1, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-05', 'L21', 'official', '某企業以詞頻–逆文件頻率（Term Frequency–Inverse Document Frequency, TF-IDF）方法分析顧客意見內容，但發現模型在處理篇 幅較長的回饋文本時，無法準確反映關鍵詞的重要性。下列何者為造 成此現象的主要原因？', '{"A":"長文本中的詞頻偏高，導致常見詞權重被過度放大","B":"長文本中缺乏明確句子邊界，造成 TF-IDF 無法計算詞頻","C":"TF-IDF 無法同時處理多份文件","D":"長文本會改變IDF（Inverse Document Frequency）的計算，使所 有詞權重趨於相近"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 5, 'iPAS 114年第2梯次中級 L21 公告試題，第5題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 5, 2, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-06', 'L21', 'official', '某企業嘗試以N-gram 語言模型（N-gram Language Model）建立客服 自動回覆系統，但發現模型生成的句子雖在片段上合理，卻缺乏整體 語意連貫性。此問題最可能源自N-gram 模型的哪一項限制？', '{"A":"N-gram 模型在訓練過程中需要龐大計算量，導致長句無法收斂","B":"N-gram 模型僅根據固定長度的前序詞建立機率估計，難以捕捉長 距離依賴關係（Long-range Dependencies）","C":"N-gram 模型缺乏語意嵌入（Semantic Embedding）層，因此無法 表徵詞語間的語意相似度","D":"N-gram 模型假設詞與詞之間相互獨立，導致無法建構上下文語意 關聯"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 6, 'iPAS 114年第2梯次中級 L21 公告試題，第6題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 6, 2, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-07', 'L21', 'official', '在企業導入的智慧監控系統中，模型以物件偵測（Object Detection）方式自動辨識影像中的人物與車輛。若評估指標採用平 均精確率（Mean Average Precision, mAP），其中 IoU （Intersection over Union）閾值設定較高時，代表下列哪一項意 義？', '{"A":"預測邊界框與真實邊界框的重疊程度越高，模型偵測結果越精 準","B":"預測邊界框與真實邊界框的誤差越大，導致mAP 數值上升","C":"模型整體精確率（Precision）降低，但召回率（Recall）上升","D":"預測邊界框的評估結果不受真實框大小影響"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 7, 'iPAS 114年第2梯次中級 L21 公告試題，第7題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 7, 2, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-08', 'L21', 'official', '關於Softmax 與Max-Pooling，下列敘述何者正確？', '{"A":"Softmax 與Max-Pooling 都會將特徵張量壓縮為單一最大值","B":"Max-Pooling 會對輸入進行機率分佈的轉換","C":"Softmax 會保留所有輸入資訊，但以比例表示；Max-Pooling 只保留區域最大值","D":"Softmax 主要用於特徵降維，而Max-Pooling 用於分類輸出"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 8, 'iPAS 114年第2梯次中級 L21 公告試題，第8題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 8, 2, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-09', 'L21', 'official', '某企業在訓練生成式AI 模型時，導入資料增強（Data Augmentation）技術以擴充訓練資料，但觀察到模型效能反而下降。 下列哪一項最可能的原因與對應改善策略最為正確？', '{"A":"增強樣本未經隨機初始化，導致模型梯度更新不穩定，應重新設 計訓練啟動流程","B":"增強後資料的特徵分佈與原始資料不一致，影響模型的泛化能 力，應檢查並調整增強策略以維持語意一致性","C":"增強樣本的比例過高，造成模型對特定資料產生偏好，應適度提 高增強比例並調整學習率","D":"增強後資料的標註可信度下降，導致訓練訊號偏差，應以半監督 學習方式重新校正資料"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 9, 'iPAS 114年第2梯次中級 L21 公告試題，第9題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 9, 3, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-10', 'L21', 'official', '如果希望同時兼顧「精確率（Precision）」和「召回率（Recall）」， 下列哪一個指標可以作為綜合評估的標準？', '{"A":"準確率（Accuracy）","B":"均方根誤差（RMSE）","C":"均方誤差（MSE）","D":"F1 分數（F1 Score）"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 10, 'iPAS 114年第2梯次中級 L21 公告試題，第10題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 10, 3, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-11', 'L21', 'official', '企業資料分析團隊使用DBSCAN（Density-Based Spatial Clustering of Applications with Noise）演算法進行顧客行為分群，並希望模 型能自動區分主要群集與雜訊資料。 在此演算法中，決定聚類結果的兩個主要超參數為下列何者？', '{"A":"特徵數與學習率","B":"K 值與距離閾值","C":"鄰域半徑（Epsilon ε）與最小點數（MinPts）","D":"交叉熵（Cross Entropy）與權重初始化"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 11, 'iPAS 114年第2梯次中級 L21 公告試題，第11題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 11, 3, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-12', 'L21', 'official', '某金融科技公司建立房價預測模型，使用多項特徵（如建坪、房齡、 樓層、總價等）進行線性迴歸分析（Linear Regression Analysis）。資料分析師發現多個特徵之間存在高度相關性，導致模 型係數不穩定、預測誤差上升。為解決此問題，下列哪一種方法最適 合？', '{"A":"繼續保留所有特徵，不進行任何處理","B":"使用主成分分析（PCA）將相關特徵轉換為彼此獨立的主成分；","C":"新增更多原始變數以提升模型表現","D":"改用分類模型進行預測"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 12, 'iPAS 114年第2梯次中級 L21 公告試題，第12題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 12, 3, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-13', 'L21', 'official', '下列何者為Kubernetes 在AI 模型部署與運行中的核心功能？', '{"A":"自動化管理模型的訓練流程與參數調校","B":"管理與協調模型服務的部署、擴展與運行環境","C":"提供AI 模型的資料儲存與版本控管功能","D":"負責深度學習推論的 GPU 加速運算"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 13, 'iPAS 114年第2梯次中級 L21 公告試題，第13題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 13, 4, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-14', 'L21', 'official', '在調整模型超參數（Hyperparameters）時，若希望避免因過度調整 參數而導致過擬合，下列哪一種做法最有效提升模型的泛化能力？', '{"A":"採用交叉驗證（Cross-Validation）於多組參數組合間反覆評 估，選擇在驗證資料上表現最穩定的設定","B":"使用早期停止機制（Early Stopping）監控訓練誤差並在收斂前 停止訓練，以防模型學習過度","C":"對輸入特徵進行標準化以減少特徵值差異帶來的過擬合風險","D":"提高模型複雜度並使用更多超參數搜尋範圍，以確保模型能充分 學習資料特徵"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 14, 'iPAS 114年第2梯次中級 L21 公告試題，第14題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 14, 4, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-15', 'L21', 'official', '在企業導入的MLOps（Machine Learning Operations）流程中， Model Registry 最常用於哪一個階段？', '{"A":"用於設定運算資源與執行環境以確保訓練穩定","B":"用於建立可重複使用的資料與特徵版本","C":"用於集中管理模型版本、訓練紀錄與部署狀態","D":"用於追蹤模型上線後的表現與漂移情況"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 15, 'iPAS 114年第2梯次中級 L21 公告試題，第15題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 15, 4, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-16', 'L21', 'official', '下列哪一種情境中最適合使用「序列到序列（Seq2Seq）」模型？', '{"A":"預測銷售趨勢曲線，輸出未來數值序列","B":"辨識文本中出現的人名、地名與組織名稱等實體資訊","C":"對輸入文本中的關鍵字進行頻率統計與可視化","D":"將輸入文字轉換成語意等價的另一段文字，如自動翻譯或摘要生 成"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 16, 'iPAS 114年第2梯次中級 L21 公告試題，第16題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 16, 4, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-17', 'L21', 'official', '在自然語言處理中，檢索增強生成（Retrieval-Augmented Generation, RAG）是一種結合語言模型與向量搜尋的技術，可有效 減少模型知識過時與產生幻覺的問題。若要建立一套高效能的RAG 系 統，下列何者為在「檢索階段」最關鍵的挑戰？', '{"A":"確保檢索到的文件能被完整納入語言模型的上下文視窗（Context Window）中進行生成；","B":"選擇使用Faiss 或ScaNN 等近似最近鄰搜尋函式庫","C":"降低嵌入模型（Embedding Model）在高維空間中的計算成本與記 憶體占用","D":"避免向量檢索結果僅具語意相似但與查詢意圖無實質關聯的情況"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 17, 'iPAS 114年第2梯次中級 L21 公告試題，第17題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 17, 4, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-18', 'L21', 'official', '當Transformer 模型發生「注意力分布過於平均（Attention Collapse）」的情形時，導致模型無法有效聚焦於關鍵資訊，下列哪 一項策略可有效改善此問題？', '{"A":"提高Query-Key 點積（Dot Product）的縮放常數","B":"在Softmax 前加入高斯雜訊（Gaussian Noise）","C":"使用 ReLU 函數取代 Softmax","D":"對注意力權重施加稀疏化約束（Sparsity Constraint）"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 18, 'iPAS 114年第2梯次中級 L21 公告試題，第18題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 18, 5, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-19', 'L21', 'official', '某研究團隊正在訓練一個針對低資源語言（如少數民族語言）的語言 模型，但該語言僅有約1 萬筆語料可用。在訓練過程中出現明顯的過 擬合現象，若希望在不新增真實語料的前提下提升模型的泛化能力， 採用下列哪一種方法最為適合？', '{"A":"將Transformer 的隱藏層維度擴增至1024，以提升表徵能力","B":"採用反向翻譯（Back-Translation）技術，以生成額外目標語句 的偽平行語料（Pseudo‑Parallel Corpus）","C":"對詞嵌入矩陣（Embedding Matrix），施加L1 正則化以壓縮模型 參數","D":"將多語言BERT（mBERT）中所有Transformer 層全部凍結以保留預 訓練知識"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 19, 'iPAS 114年第2梯次中級 L21 公告試題，第19題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 19, 5, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-20', 'L21', 'official', '在使用生成對抗網路（GAN）進行人臉影像生成時，若出現「模式崩 潰」（Mode Collapse）現象，下列哪一種方法最常被用來有效解決此 問題？', '{"A":"在鑑別器中加入梯度懲罰（Gradient Penalty）以穩定訓練過 程","B":"採用 Wasserstein 距離（WGAN 損失）替代原始的 GAN 損失函 數","C":"對生成器輸入的潛在向量加入隨機擾動","D":"使用多尺度鑑別器架構以提高對多樣性的判別能力"}'::jsonb, array['L21103']::text[], 2, array['????', '114', '???']::text[], null, 20, 'iPAS 114年第2梯次中級 L21 公告試題，第20題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 20, 5, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-21', 'L21', 'official', '在多模態 AI 模型訓練或推論過程中，遇到某一模態資料缺失（例如 僅有影像資料但缺少文本說明），下列哪一種策略最有效維持模型效 能？', '{"A":"以零向量或固定向量填充缺失模態輸入","B":"訓練具備模態缺失感知能力的模型，使其適應缺失狀況","C":"利用生成模型（如 GAN 或自迴歸模型）預測並補全缺失模態資 料","D":"直接捨棄缺少模態的樣本，避免干擾訓練或推論"}'::jsonb, array['L21103']::text[], 2, array['????', '114', '???']::text[], null, 21, 'iPAS 114年第2梯次中級 L21 公告試題，第21題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 21, 5, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-22', 'L21', 'official', '某電商平台開發的顧客流失預測模型在上線數月後，預測準確率明顯 下降。專案團隊懷疑顧客行為模式改變，導致模型輸入特徵的分佈與 原始訓練資料不同，出現典型的資料漂移（Data Drift）問題。為了 偵測並確認資料分佈是否發生變化，下列哪一種作法最合適？', '{"A":"定期重新訓練模型以應對外部變化","B":"提升模型複雜度以捕捉更多資料變異性","C":"增加測試資料量以提高評估準確度","D":"計算輸入特徵分佈間的KL 散度（KL Divergence）"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 22, 'iPAS 114年第2梯次中級 L21 公告試題，第22題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 22, 6, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-23', 'L21', 'official', '某大型醫院即將部署一套輔助診斷的AI 系統，為降低對臨床流程的 衝擊，同時確保風險可控與回饋可收斂，應採取何種『漸進式部署』 （Phased Rollout）策略最為合適？', '{"A":"從單一專科（如放射科）或特定病房開始啟用，逐步擴展至全 院","B":"先部署於病例量較高的急診單位，加速收集高頻使用回饋","C":"僅在夜班或離峰時段啟用，避免影響主要臨床工作負載","D":"在使用者界面啟用提示模式，讓全院同步體驗但不影響診斷流程"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 23, 'iPAS 114年第2梯次中級 L21 公告試題，第23題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 23, 6, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-24', 'L21', 'official', '某金融機構的AI 風控系統遭受對抗性攻擊，駭客透過對輸入特徵進 行微小但惡意的擾動，成功欺騙了模型。為了從根本上解決模型自身 對這類攻擊的脆弱性，下列何者並非針對此種攻擊型態的技術手段？', '{"A":"強化資料前處理，用以過濾掉格式不符或數值極端異常的輸入","B":"在模型訓練階段導入對抗樣本訓練，以提升模型對惡意特徵擾動 的辨識與防禦能力","C":"於推論後階段使用規則引擎，以確保模型的預測結果不違反既有 的業務硬性規定","D":"在模型部署環境中強化網路防火牆，以阻擋來自未授權來源的網 路連線"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 24, 'iPAS 114年第2梯次中級 L21 公告試題，第24題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 24, 6, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-25', 'L21', 'official', '某企業部署生成式AI 系統協助行銷與內容產出，但近期遭質疑部分 生成內容可能涉及著作權侵權。為降低企業在法律層面的潛在責任與 風險，下列哪一項策略最能有效預防侵權問題產生？', '{"A":"對生成內容進行語意相似度比對，自動標註可能涉及既有著作的 輸出結果，以降低侵權風險","B":"建立訓練資料篩選與授權驗證機制，排除未授權或高風險資料來 源","C":"在訓練與微調過程中採用差分隱私技術，避免模型記憶特定受著 作權保護的樣本","D":"在模型輸出端嵌入浮水印（Watermarking）或數位指紋（Digital Fingerprint）技術，以確保生成內容可追溯"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 25, 'iPAS 114年第2梯次中級 L21 公告試題，第25題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 25, 6, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-26', 'L21', 'official', '在房價預測任務中，若發現特徵如「房間數」與「坪數」存在高度多 重共線性（Multicollinearity），為降低共線性對模型參數估計的負 面影響，應優先選擇下列哪種模型？', '{"A":"不受多重共線性影響的決策樹模型","B":"傳統線性迴歸模型，不含正則化項","C":"支持向量機搭配線性核函數","D":"含L1 正則化的LASSO 迴歸模型"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 26, 'iPAS 114年第2梯次中級 L21 公告試題，第26題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 26, 7, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-27', 'L21', 'official', '某企業需分析半結構化的系統日誌（JSON 格式），以提取關鍵的時序 特徵供故障預測模型使用。考量日誌結構複雜且包含巢狀欄位 （Nested Fields），下列哪一種策略最有效且實務可行？', '{"A":"先將JSON 資料扁平化轉成CSV，再對欄位計算統計量（如均值、 次數）作為特徵","B":"使用遞歸神經網路（RNN）直接輸入原始JSON 字串進行時序特徵 抽取","C":"設計遞迴函式展開巢狀欄位，並基於時間窗口（Time Window）進 行聚合與特徵萃取","D":"只保留時間戳記欄位，忽略其他巢狀內容以簡化特徵工程"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 27, 'iPAS 114年第2梯次中級 L21 公告試題，第27題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 27, 7, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-28', 'L21', 'official', '在一個同時包含連續型特徵與類別型特徵的資料集中，若希望透過適 當的特徵工程流程來提升模型整體表現，下列哪一種作法最為合適？', '{"A":"將類別型特徵使用標籤編碼（Label Encoding）轉換後，與連續 特徵直接合併進行模型訓練","B":"將連續特徵進行離散化（Discretization）或分桶（Binning）轉 為類別型特徵，統一以類別方式處理","C":"對連續特徵做標準化（Standardization），類別特徵採用目標編 碼（Target Encoding），並生成交互特徵提升模型表現","D":"只保留連續特徵，忽略類別型變量以簡化模型"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 28, 'iPAS 114年第2梯次中級 L21 公告試題，第28題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 28, 7, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-29', 'L21', 'official', '某AI 開發團隊為提升模型開發效率及品質控制，計畫實施持續整合 （Continuous Integration, CI）流程。下列哪一項做法最符合CI 的核心實踐，且能有效減少整合風險？', '{"A":"在主分支（Main Branch）每日固定時間手動合併並執行完整測試 流程","B":"每次程式碼提交（Commit）後自動觸發建置、單元測試及靜態程 式碼分析","C":"於模型訓練完成後，定期安排開發團隊回顧並合併程式碼","D":"透過自動化部署腳本，將模型在特定時間點批次釋出到測試環境"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 29, 'iPAS 114年第2梯次中級 L21 公告試題，第29題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 29, 8, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-30', 'L21', 'official', '某銀行計劃將AI 詐欺偵測模組整合至核心交易系統，主管機關要求 全流程必須符合金融監管對「不可否認性（Non-repudiation）」的資 訊安全規範，以確保日後能進行法務追蹤與稽核。下列哪一項措施最 能確保此要求的落實？', '{"A":"為每筆AI 模型推論記錄其輸入與輸出結果的加密雜湊值 （Hash），並簽署數位簽章以確保不可竄改性","B":"優化模型效能以降低平均推論延遲至100ms 以下，提升使用者體 驗","C":"增加主機備援數量，以確保系統在故障時持續可用","D":"將模型推論請求導入負載平衡器，避免單點壅塞導致服務延遲"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 30, 'iPAS 114年第2梯次中級 L21 公告試題，第30題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 30, 8, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-31', 'L21', 'official', '某AI 服務系統每次推論請求需約1 秒完成，且必須支撐高達10,000 次請求每秒（RPS）的流量。為確保系統具備高可用性且能穩定應付 流量峰值，下列哪一種架構方案最為合適？', '{"A":"依賴單台超高效能伺服器進行垂直擴展，提升硬體規格","B":"採用容器化部署並水平擴展服務實例，結合自動彈性伸縮機制 （Auto Scaling）","C":"限制最大併發連線數，以避免系統過載","D":"增加批次處理大小，一次同時處理上千筆請求"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 31, 'iPAS 114年第2梯次中級 L21 公告試題，第31題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 31, 8, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-32', 'L21', 'official', '某企業已將AI 模型部署於生產環境，為確保系統持續穩定運作，並 能提前偵測模型效能可能衰退，技術團隊希望透過監控指標進行預 警。 下列哪一項監控指標最具預測效力，能提早發現模型效能下滑風險？', '{"A":"系統CPU 與記憶體使用率波動幅度","B":"模型推論結果的置信度（Confidence）分佈變化趨勢","C":"API 平均回應時間與延遲百分位數變化；","D":"輸入特徵與訓練資料分布差異的PSI（Population Stability Index）指數"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 32, 'iPAS 114年第2梯次中級 L21 公告試題，第32題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 32, 8, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-33', 'L21', 'official', '企業團隊在使用Word2Vec 模型訓練客服文本語料時，若訓練資料量 龐大且希望模型能更有效捕捉罕見詞的語意關聯，下列哪一種訓練策 略最為適合？', '{"A":"採用Skip-gram 模型，但以隨機初始化權重加快高頻詞的訓練收 斂","B":"採用CBOW 模型（Continuous Bag of Words Model）並結合TF- IDF 權重以強化低頻詞表示","C":"採用Skip-gram 模型，利用中心詞預測周圍詞語，能更有效學習 低頻詞關係","D":"採用CBOW 模型（Continuous Bag of Words Model），利用周圍詞 預測中心詞，能提升罕見詞的語意穩定度"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 33, 'iPAS 114年第2梯次中級 L21 公告試題，第33題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 33, 9, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-34', 'L21', 'official', '在自駕車影像辨識系統中，開發團隊希望模型能同時辨識每個像素所 屬的物件類別（例如道路、建築、行人），又能區分出同類物件的不 同個體（例如多位行人）。此時最適合採用下列哪一項電腦視覺技 術？', '{"A":"語義分割（Semantic Segmentation）","B":"物件偵測（Object Detection）","C":"實例分割（Instance Segmentation）","D":"全景分割（Panoptic Segmentation）"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 34, 'iPAS 114年第2梯次中級 L21 公告試題，第34題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 34, 9, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-35', 'L21', 'official', '某媒體公司計畫導入CLIP（Contrastive Language–Image Pre- training）模型，以協助大量影像自動標註與搜尋，並希望在無需新 增標訓資料的情況下，僅透過文字提示（Text Prompt）即可識別影 像內容。請問此應用情境中，CLIP 能夠達成的關鍵技術特性為何？', '{"A":"透過圖文對比式學習（Contrastive Learning）將影像與文字映 射至共同嵌入空間（Shared Embedding Space），可直接以語意相似 度進行零樣本分類","B":"透過影像增強與特徵擴散降低標訓資料需求","C":"以監督式學習結合多層感知器（Multilayer Perceptron, MLP） 進行影像特徵分類","D":"以自迴歸生成模型（Autoregressive Model）逐步生成文字標籤 描述影像內容"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 35, 'iPAS 114年第2梯次中級 L21 公告試題，第35題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 35, 9, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-36', 'L21', 'official', '某資料科學團隊在開發預測模型時，針對多種模型設定（如學習率、  樹深度、正則化係數等）進行系統化測試，希望找出在驗證資料上表 現最穩定的組合。此過程最可能採用下列哪一種方法？', '{"A":"使用交叉驗證（Cross Validation）反覆評估模型以降低過擬合 風險","B":"透過網格搜尋（Grid Search）在多組超參數設定中進行系統化搜 尋與評估","C":"以隨機搜尋（Random Search）快速探索部分參數空間以提升搜尋 效率","D":"採用貝葉斯優化（Bayesian Optimization）根據歷次結果動態調 整搜尋方向"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 36, 'iPAS 114年第2梯次中級 L21 公告試題，第36題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 36, 9, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-37', 'L21', 'official', '某公司正在訓練一個大型語音合成模型，開發團隊使用多台GPU 進行 訓練，但經常出現 GPU 記憶體不足問題。由於模型架構已固定且無 法更換硬體，團隊希望在維持模型效能與收斂品質的前提下，下列哪 一種方法最有效降低單張 GPU 的記憶體壓力？', '{"A":"減少訓練資料量以降低記憶體使用","B":"採用較小的批次大小（Batch Size）並搭配資料分片（Data Sharding）分散訓練負載","C":"增加學習率（Learning Rate）以加快收斂速度","D":"改用測試資料集（Test Set）進行部分訓練以節省空間"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 37, 'iPAS 114年第2梯次中級 L21 公告試題，第37題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 37, 10, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-38', 'L21', 'official', '某影像設計團隊在使用Stable Diffusion 生成4K 級產品圖時，發現 影像邊緣與細節存在顆粒化與模糊現象。 若僅能在生成階段進行調整，希望提升畫面清晰度與紋理層次，同時 避免過度平滑，下列哪一項作法最適合？', '{"A":"降低取樣步數，以縮短生成時間","B":"增加取樣步數並選擇高品質取樣器，以強化細節還原度","C":"提高CFG（Classifier-Free Guidance）值，使生成結果更具創意 與多樣性","D":"改用低解析度輸入以降低計算成本"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 38, 'iPAS 114年第2梯次中級 L21 公告試題，第38題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 38, 10, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-39', 'L21', 'official', '某企業的資料科學團隊利用ARIMA 模型（AutoRegressive Integrated Moving Average Model）預測每週產品銷售量。模型建 立完成後，分析人員發現預測誤差隨時間呈現週期性波動，且自相關 函數（ACF）顯示殘差在多個時滯（Lag）上仍顯著不為零。根據上述 現象，最合理的模型診斷結論為何？', '{"A":"模型殘差符合白噪音（White Noise）假設，預測表現穩定；","B":"模型殘差雖有輕微異常，但可視為隨機誤差忽略不計","C":"模型存在配適不足（Underfitting）問題，需重新調整 p 或 q 參數以捕捉時間依賴性","D":"殘差特性不影響預測結果，無須進一步修正"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 39, 'iPAS 114年第2梯次中級 L21 公告試題，第39題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 39, 10, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-40', 'L21', 'official', '下列哪一項最正確地描述了VAE（Variational Autoencoder）、GAN （Generative Adversarial Network）與擴散模型（Diffusion Model）在多模態潛在空間對齊（Latent Alignment）與生成策略上 的根本差異？', '{"A":"VAE 透過顯式潛在變數建模實現跨模態對齊，適合捕捉整體語意結 構但生成解析度有限；GAN 透過對抗損失（Adversarial Loss）在不 同模態間學習分佈映射，生成品質高但穩定性差；擴散模型則以條件 化噪聲反推（Conditional Denoising）方式實現高保真跨模態生 成，兼具穩定性與多樣性","B":"VAE 與Diffusion Ｍodel 均屬隱式生成架構，主要依賴對抗式訓 練實現跨模態對齊；GAN 則以顯式後驗估計方式提升樣本一致性","C":"VAE 與GAN 均使用馬爾可夫鏈（Markov Chain）進行跨模態轉換； Diffusion Model 則透過 KL 散度最小化學習語意對應。","D":"三者在多模態應用中皆依賴同一潛在表徵空間（Shared Latent Space），僅在解碼器結構不同而已"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 40, 'iPAS 114年第2梯次中級 L21 公告試題，第40題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 40, 11, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-41', 'L21', 'official', '在進行超參數調校（Hyperparameter Tuning）時，若直接在K-Fold 交叉驗證（Cross-Validation）的資料上同時調整模型參數並評估效 能，最可能導致下列哪一種問題？', '{"A":"模型的交叉驗證結果出現過度樂觀偏差（Over-optimistic Bias），因測試摺資料間接參與參數選擇，造成資料洩漏（Data Leakage）","B":"模型會在每一摺（Fold）內反覆調整參數，導致訓練不穩與過度 正則化","C":"因交叉驗證資料被重複使用，造成效能方差增大，無法獲得穩定 估計","D":"K-Fold 交叉驗證的假設與超參數搜尋相衝突，導致驗證過程失效"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 41, 'iPAS 114年第2梯次中級 L21 公告試題，第41題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 41, 11, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-42', 'L21', 'official', '若部署一個深度學習模型至金融風控系統，該模型採用鑑別式架構 （如Transformer Classifier）。然而上線後，模型對新樣本的分類 錯誤率顯著上升，經檢查發現，輸入資料分佈已與原訓練集明顯不 同。針對此情形，下列哪一種應對策略最為適合？', '{"A":"改用生成對抗網路（GAN）生成新樣本並混入訓練集","B":"改用邏輯迴歸模型（Logistic Regression）以提升穩定性","C":"增加模型容量（Model Capacity），以學習更多樣本差異","D":"使用變分自編碼器（VAE）監控潛在空間分佈，偵測輸入資料偏移"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 42, 'iPAS 114年第2梯次中級 L21 公告試題，第42題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 42, 11, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-43', 'L21', 'official', '某金融科技公司欲導入AI 模型協助客服郵件自動分類（投訴、詢 問、表揚）。團隊同時考慮兩種模型設計： 方案 A（生成式路徑）：採用VAE 建構潛在語意空間，再結合下游分 類器進行標籤預測； 方案 B（鑑別式路徑）：採用BERT Classifier 直接根據輸入文本進 行監督式分類。 現有標註資料約 2,000 筆，資料分佈均勻但擴充成本高。若團隊希 望公平比較兩種模型的資料利用效率與泛化能力，下列哪一種實驗設 計最能突顯兩者的本質差異？', '{"A":"在完整資料集上分別訓練兩者，並比較其分類準確率 （Accuracy）與推論時間","B":"在低資源情境（Low-resource Setting）下，逐步減少標註比例 （100%、50%、10%），比較其F1-score","C":"使用GAN 自動生成文本樣本補足資料，觀察兩模型在資料增強後 的精確率（Precision）差異","D":"在相同訓練資料上固定輸入維度，僅調整模型參數量，比較其對 過擬合的敏感度"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 43, 'iPAS 114年第2梯次中級 L21 公告試題，第43題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 43, 12, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-44', 'L21', 'official', '某電信公司希望建立一個模型來預測顧客是否即將流失，並進一步模 擬不同促銷或服務策略下顧客的行為變化，以生成多樣化的虛擬樣本 資料進行A/B 測試與行銷策略評估。若要同時兼顧預測與資料生成的 需求，最適合採用下列哪一種方法？', '{"A":"使用傳統隨機森林（Random Forest）","B":"使用邏輯迴歸（Logistic Regression）模型","C":"使用變分自編碼器（Variational Autoencoder, VAE）或生成對 抗網路（Generative Adversarial Network, GAN）","D":"使用強化學習代理（Reinforcement Learning Agent）"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 44, 'iPAS 114年第2梯次中級 L21 公告試題，第44題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 44, 12, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-45', 'L21', 'official', '進行影像分類任務時，研究團隊嘗試利用主成分分析（Principal Component Analysis, PCA）將輸入特徵從1024 維降至100 維，並將 降維後的資料輸入支持向量機（Support Vector Machine, SVM）模 型進行訓練。關於此作法，下列哪一項描述最為合理？', '{"A":"PCA 保留的主成分必然能提升SVM 的分類準確率","B":"使用原始高維資料通常更能保留資訊，因此PCA 沒有實際意義","C":"PCA 可讓SVM 自動適用於非線性（Nonlinear）資料集","D":"降維後可降低訓練時間並減少過擬合（Overfitting）風險"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 45, 'iPAS 114年第2梯次中級 L21 公告試題，第45題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 45, 12, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-46', 'L21', 'official', '某企業的AI 模型已部署於線上服務環境中，用於即時預測顧客流失 機率。近期團隊注意到模型預測準確率逐漸下降，但系統運作正常且 未出現錯誤訊息。經分析發現，近期輸入資料的分布與模型訓練資料 相比出現顯著偏移。若要在MLOps 流程中主動偵測並預警此類問題， 最應採用下列哪項措施？', '{"A":"建立即時的資料漂移（Data Drift）與概念漂移（Concept Drift）監測機制","B":"將模型轉換為量化版本以降低延遲","C":"增加模型超參數調整次數以強化適應性","D":"使用固定隨機種子（Random Seed）確保訓練穩定"}'::jsonb, array['L21301']::text[], 2, array['????', '114', '???']::text[], null, 46, 'iPAS 114年第2梯次中級 L21 公告試題，第46題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 46, 13, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-47', 'L21', 'official', '某金融科技公司導入多任務學習架構，讓單一 Transformer 模型同 時執行OCR（Optical Character Recognition）後的文檔分類以及命 名實體辨識（Named Entity Recognition, NER）任務， 以協助自動歸檔與抽取關鍵金融資訊。在部署初期，團隊發現當模型 的NER 準確率（Accuracy）提升時，文檔分類準確率反而下降。若模 型架構正確且資料品質良好，下列哪一項最可能是造成此現象的原 因？', '{"A":"模型架構無法同時支援文字分類與序列標註任務（Sequence Labeling）","B":"文檔分類任務不需要語意化表徵（Contextualized Representation）","C":"損失函數（Loss Function）未進行權重平衡，導致任務間競爭","D":"所使用的BERT 模型無法支援多任務輸出頭（Multi-Head Outputs）"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 47, 'iPAS 114年第2梯次中級 L21 公告試題，第47題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 47, 13, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-48', 'L21', 'official', '某數據工程師使用DBSCAN 演算法對一份數百萬筆的高維顧客資料進 行聚類分析，但發現程式執行速度極慢，甚至出現記憶體不足的情 況。若要在不改變演算法核心邏輯的前提下，最有效提升其運算效率 的作法為何？', '{"A":"改用以平均連結（Average Linkage）為基礎的階層式群集法 （Hierarchical Clustering）；","B":"採用高效率的距離索引結構（Distance Index Structure），例如 KD-Tree 或 Ball Tree","C":"將 ε（Epsilon）參數調得極小，以減少鄰近點的數量","D":"在資料前處理時增加標準化後的特徵維度數"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 48, 'iPAS 114年第2梯次中級 L21 公告試題，第48題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 48, 13, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-49', 'L21', 'official', '某電商平台導入AI 情感分析模型，用以自動偵測顧客評論中的負面 情緒並觸發客服機制。然而，上線後發現模型在面對不同語言或族群 書寫風格的評論時表現不一致，例如部分語氣強烈的正面評論被誤判 為負面，而禮貌但含批評意圖的評論卻被判為中性。若從技術與資料 治理的角度分析，下列哪一項描述不正確？', '{"A":"模型未啟用詞嵌入正規化（Embedding Normalization）可能造成 語意距離不穩定，導致預測誤差","B":"訓練語料若偏向特定文化或語氣特徵，可能使模型產生內隱偏誤 （Implicit Bias）","C":"模型若訓練資料來源不平衡，容易導致對不同語言或族群風格的 情緒判斷不準確","D":"Transformer 架構能捕捉上下文語意，但若訓練資料偏差仍存在， 模型仍可能學習到偏誤判斷"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 49, 'iPAS 114年第2梯次中級 L21 公告試題，第49題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 49, 14, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-114-50', 'L21', 'official', '某設計師使用公司內部建置的生成式AI 工具製作行銷素材，並輸入 提示語（Prompt）：「請生成一張模特兒手持品牌飲料、背景為海邊夕 陽的照片」。系統能正確生成主要主題與場景，但輸出的圖像中，品 牌標誌顏色常有誤差，或人物手部姿勢顯得不自然。若從多模態生成 模型的技術機制分析，此現象最可能是下列哪一項原因所造成？', '{"A":"擴散式生成模型的去雜訊過程出現隨機梯度漂移，導致影像像素 錯誤","B":"提示語過長造成Transformer 的位置編碼超出上下文限制，導致 生成混亂","C":"CLIP 模型中的文字編碼器與影像編碼器在語意嵌入空間未充分對 齊，導致跨模態理解偏差","D":"模型未採用對比學習（Contrastive Learning）損失函數，無法 建立多模態語意關聯"}'::jsonb, array['L21101']::text[], 2, array['????', '114', '???']::text[], null, 50, 'iPAS 114年第2梯次中級 L21 公告試題，第50題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=28a0c0d2-2165-45fe-994d-df07dc0eb50e_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%A2%AF%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%80%E7%A7%91_%E4%BA%BA%E5%B7%A5%E6%99%BA%E6%85%A7%E6%8A%80%E8%A1%93%E6%87%89%E7%94%A8%E8%88%87%E8%A6%8F%E5%8A%83%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 50, 14, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-01', 'L21', 'official', '某工程師正在建置一套法律文件解析系統，在進行資訊擷取（Information Extraction）前，需要對文本進行詞性標註（Part-of-Speech Tagging, POS Tagging）。 請問此步驟的主要目的為何？', '{"A":"將文本翻譯為其他語言以利跨語言分析","B":"將文本切分為基本詞彙單位，以便後續處理","C":"判斷文本中各詞彙的情感傾向","D":"為每個詞彙標記其語法類別，如名詞、動詞與形容詞"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 51, 'iPAS 115年第1梯次中級 L21 公告試題，第1題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 1, 1, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-02', 'L21', 'official', '一家新創公司希望對Llama3 70B 模型進行領域微調（Domain Fine-Tuning）以建 立企業專用助理，但GPU 記憶體有限，無法支撐完整模型的反向傳播梯度計算。 工程師希望凍結（freeze）原模型權重、僅訓練少量額外參數的前提下，評估採用 LoRA（Low-Rank Adaptation）方案。請問LoRA 在此場景下的主要優勢為何？', '{"A":"透過知識蒸餾（Knowledge Distillation）將70B 模型壓縮為較小的學生模型","B":"對原始模型各層權重進行剪枝（Pruning），移除低重要性參數後再進行微調","C":"凍結原始預訓練權重，僅在各層加入低秩分解的可訓練矩陣，大幅降低可訓練 參數量與GPU 記憶體需求","D":"將模型中的注意力機制改為稀疏注意力（Sparse Attention），以降低長序列計 算成本"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 52, 'iPAS 115年第1梯次中級 L21 公告試題，第2題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 2, 1, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-03', 'L21', 'official', '某工程師在建構搜尋引擎的詞向量模型時，語料庫規模達數十億token，且包含 大量長尾詞彙（Long-tail Terms）。他在Word2Vec 的CBOW 與Skip-gram 兩種訓 練策略之間進行選擇，需考量訓練效率與低頻詞表示品質之差異。下列何者最能 準確地反映兩者在此情境下的取捨？', '{"A":"CBOW 對長尾詞表現更好，因為它透過多個上下文詞的平均來強化稀疏詞的 訓練訊號","B":"CBOW 訓練速度較快、整體語意平滑，但對低頻詞的向量品質較差；Skip-gram 以中心詞預測周圍詞，對長尾詞累積更多訓練樣本，向量品質較優","C":"Skip-gram 訓練速度更快，因為每次只需預測單一目標詞，計算量低於CBOW","D":"兩者對低頻詞的表現完全相同，差異僅在於訓練時的Batch 組織方式"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 53, 'iPAS 115年第1梯次中級 L21 公告試題，第3題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 3, 1, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-04', 'L21', 'official', '某金融科技公司的工程師正在準備內部客服對話與交易紀錄文本，進行BERT 模 型的預訓練，以提升模型對金融語境的理解能力，並採用遮蔽語言建模（Masked Language Model, MLM）作為訓練任務。請問MLM 的核心訓練目標為何？', '{"A":"讓模型自左至右逐token 生成句子，學習自迴歸語言模型（Autoregressive LM） 能力","B":"透過對抗訓練（Adversarial Training）縮小真實句與生成句之間的語意差異；","C":"隨機遮蔽輸入序列中部分token，訓練模型根據雙向上下文預測被遮蔽的原始 內容","D":"透過遮蔽低頻詞來減少詞彙表大小，降低Embedding 的記憶體使用"}'::jsonb, array['L21101']::text[], 2, array['????', '115', '???']::text[], null, 54, 'iPAS 115年第1梯次中級 L21 公告試題，第4題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 4, 1, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-05', 'L21', 'official', '某電商平台的工程師在開發商品評論情感分析系統時，發現使用One-Hot 編碼無 法表達詞語之間的語意關係，且隨著詞彙表擴大，向量維度與記憶體需求快速增 加。工程師因此改用Word2Vec 進行詞語表示。請問Word2Vec 從根本上解決了 上述問題的哪項限制？', '{"A":"建立詞語之間的序列依賴關係，以捕捉長距離上下文語意","B":"根據詞語在語料中的出現頻率調整其重要性，使模型更重視高頻詞","C":"降低詞彙表示的維度，同時保留語意結構，避免高維稀疏表示所帶來的限制","D":"透過監督式學習利用標註語料，提升詞語分類的準確性"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 55, 'iPAS 115年第1梯次中級 L21 公告試題，第5題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 5, 2, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-06', 'L21', 'official', '某自駕車感知系統需要在同一張影像中同時完成道路、建築、行人的逐像素分類， 並且能夠區分畫面中兩名相鄰行人（標記為「行人#1」和「行人#2」）。工程師在 選擇語義分割（Semantic Segmentation）與實例分割（Instance Segmentation）時， 請問兩者的根本差異為何？', '{"A":"實例分割對每個像素進行分類但不產生Bounding Box；語義分割產生 Bounding Box 但不進行像素級標記","B":"實例分割僅用於影像層級的類別分類，語義分割才進行逐像素標記","C":"語義分割將每個像素分配至預定義類別，但同一類別內的不同個體無法區分； 實例分割能對同一類別的不同物件（如兩名行人）分別建立獨立遮罩（Mask）","D":"語義分割與實例分割皆為逐像素分類任務，但兩者在是否需要區分不同物件 個體上並無差異"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 56, 'iPAS 115年第1梯次中級 L21 公告試題，第6題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 6, 2, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-07', 'L21', 'official', '某大型超市的防損系統需要即時偵測多名顧客各自手持的購物籃、手機與商品， 並需對每個物件進行精確區域標記（Pixel-level Mask），同時能區分畫面中不同個 體（即使不同顧客拿著相同商品，也需分別標記）。請問下列哪一項技術最適合此 場景的需求？', '{"A":"影像分類（Image Classification）","B":"目標檢測（Object Detection）","C":"實例分割（Instance Segmentation）","D":"語義分割（Semantic Segmentation）"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 57, 'iPAS 115年第1梯次中級 L21 公告試題，第7題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 7, 2, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-08', 'L21', 'official', '某工程師訓練了一個皮膚病變二元分類模型（惡性/良性），在向臨床醫師報告模型效能時，使用ROC 曲線（Receiver Operating Characteristic Curve）進行呈現。請問ROC 曲線的橫軸（X 軸）與縱軸（Y 軸）分別代表哪些指標，且在醫療情境中代表哪一種意義？', '{"A":"X 軸為準確率（Accuracy），Y 軸為召回率（Recall），表示模型整體分類正確 比例與偵測能力","B":"X 軸為假陽率（False Positive Rate, FPR），Y 軸為真陽率（True Positive Rate, TPR），反映誤診健康個體的風險與正確識別病患的能力","C":"X 軸為精確率（Precision），Y 軸為召回率（Recall），表示預測為陽性樣本的準 確性與完整性","D":"X 軸為IoU 閾值，Y 軸為mAP，反映物件偵測模型在不同重疊條件下的表現"}'::jsonb, array['L21102']::text[], 2, array['????', '115', '???']::text[], null, 58, 'iPAS 115年第1梯次中級 L21 公告試題，第8題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 8, 2, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-09', 'L21', 'official', '某團隊在監控影像分類模型的線上效能時，透過儀表板呈現混淆矩陣（Confusion Matrix），以觀察模型預測結果與實際標籤的分佈情形。請問下列哪一項無法從混 淆矩陣中直接計算？', '{"A":"精確率（Precision）","B":"準確率（Accuracy）","C":"召回率（Recall）","D":"ROC 曲線下面積（AUC）"}'::jsonb, array['L21104']::text[], 2, array['????', '115', '???']::text[], null, 59, 'iPAS 115年第1梯次中級 L21 公告試題，第9題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 9, 3, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-10', 'L21', 'official', '某工廠導入即時影像瑕疵偵測系統，需在高頻影像流中進行快速推論。工程師在 YOLO 與Faster R-CNN 兩種物件偵測架構之間進行評估，請問下列哪一個針對 兩者在偵測流程設計上的差異最為正確？', '{"A":"YOLO 採用單階段偵測，直接從整張影像預測物件位置與類別；Faster R-CNN 則先產生候選區域再進行分類","B":"YOLO 與Faster R-CNN 皆採用兩階段流程，但在特徵擷取方式上有所不同","C":"YOLO 採用單階段架構，主要透過增加候選區域數量來提升偵測準確率","D":"Faster R-CNN 採用單階段偵測方式，將物件定位與分類整合於同一模型中"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 60, 'iPAS 115年第1梯次中級 L21 公告試題，第10題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 10, 3, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-11', 'L21', 'official', '某工程師在分析Transformer 架構時，發現自注意力機制（Self-Attention）能夠有 效提升模型對序列中長距離依賴關係的建模能力。請問Self-Attention 的核心功能 為何？', '{"A":"透過隱藏狀態的遞迴傳遞，逐步累積序列中的上下文資訊","B":"讓序列中每個token 能與其他所有token 建立關聯，並根據重要性分配權重","C":"對輸入序列進行局部運算，以捕捉相鄰詞之間的關係","D":"將整個序列壓縮為固定長度表示，以提供後續任務使用"}'::jsonb, array['L21101']::text[], 2, array['????', '115', '???']::text[], null, 61, 'iPAS 115年第1梯次中級 L21 公告試題，第11題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 11, 3, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-12', 'L21', 'official', '某工程師在設計一個二元分類器（Binary Classifier）時，考慮在輸出層使用Sigmoid 函數。請問Sigmoid 函數的主要特性與限制為何？', '{"A":"可將輸入轉換為任意實數範圍，適合用於迴歸任務","B":"可將輸入壓縮至(0, 1)區間，可解釋為機率值，但在輸入值過大或過小時可能產生梯度消失問題；","C":"可將輸入轉換為多類別機率分布，常用於多分類任務","D":"可在整個輸入範圍內梯度保持穩定，適合用於深層神經網路"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 62, 'iPAS 115年第1梯次中級 L21 公告試題，第12題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 12, 3, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-13', 'L21', 'official', '某公司評估兩種方案，將大型語言模型客製化為內部客服助理：方案A 為提示微 調（Prompt Tuning），在輸入端加入可學習的軟提示（Soft Prompt）；方案B 為傳 統微調（Fine-Tuning），以標註問答資料調整模型。兩方案最本質的技術差異為 何？', '{"A":"提示微調主要用於降低推論延遲，而傳統微調則用於提升模型容量","B":"兩者技術本質相同，差別僅在於學習率（Learning Rate）設定不同","C":"傳統微調通常需要更新模型參數，而提示微調主要透過調整輸入表示來影響模 型行為","D":"提示微調與傳統微調的差異僅在於是否使用預訓練模型"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 63, 'iPAS 115年第1梯次中級 L21 公告試題，第13題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 13, 4, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-14', 'L21', 'official', '某工程師計劃將通用LLM 在醫療問答語料上進行監督微調（Supervised Fine- Tuning, SFT），但發生了災難性遺忘（Catastrophic Forgetting）問題。在計算資源 有限的情況下，工程師希望透過調整微調策略來緩解此問題。下列哪一種訓練設 計最能有效率地學習新任務的同時保留原有能力？', '{"A":"凍結大部分預訓練參數，僅對少量新增模組（如LoRA 層）進行微調，並控制 更新範圍以減少對原有知識的干擾","B":"提高學習率（Learning Rate）並縮短訓練步數，使模型快速收斂至新任務，避 免長時間訓練造成遺忘","C":"僅使用醫療語料進行多輪訓練，強化模型對新任務的專注程度","D":"增加批次大小（Batch Size）以穩定梯度更新，使模型同時保留舊知識與學習 新知識"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 64, 'iPAS 115年第1梯次中級 L21 公告試題，第14題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 14, 4, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-15', 'L21', 'official', '某企業建置一套多代理人（Multi-Agent）系統，由一個Orchestrator Agent 負責任 務分配，多個Worker Agent 分別執行網路搜尋、程式撰寫與結果彙整。若 Orchestrator 發現某Worker Agent 回傳結果品質不符合預期，從系統容錯與任務 可靠性角度，下列哪一項機制最能確保整體任務仍能正確完成？', '{"A":"直接採用該Worker Agent 的輸出，避免重試機制造成延遲","B":"Orchestrator 具備結果評估能力，對不合格結果觸發重試（Retry）或重新分配 給不同Worker，並記錄失敗原因供後續改善","C":"強制所有Worker Agent 統一使用相同的LLM 模型，以減少輸出差異","D":"當任何一個Worker 失敗時，整個Multi-Agent 任務直接中止並通知使用者重 新啟動"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 65, 'iPAS 115年第1梯次中級 L21 公告試題，第15題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 15, 4, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-16', 'L21', 'official', '一位工程師正在實作一個ReAct 框架的AI Agent，該Agent 需要回答「台灣目前最大的電動車充電站營運商是哪間公司，以及其充電樁總數」。Agent 的工具清單如下：
•web_search(query)：回傳搜尋結果摘要
•get_webpage(url)：回傳網頁內文
•calculator(expression)：回傳計算結果
•get_current_date()：回傳今日日期
工程師設計了以下的System Prompt 與ReAct Loop，請問此Agent 設計存在哪些問題？應如何改善？
[System Prompt]
你是一個資料查詢助理。每次只能使用一個工具。當你知道答案時，直接輸出最終答案。
[第一輪 Agent 輸出]
Thought: 我已經知道台灣電動車市場的概況，不需要搜尋，可以直接回答。
Action: 無
Answer: 台灣最大充電站營運商是XX 公司，共有500 個充電樁。', '{"A":"System Prompt 未要求Agent 在回答前使用工具驗證，導致直接依賴既有知識 產生幻覺（Hallucination）；應明確規定即時性問題需先執行web_search","B":"工具清單提供了calculator 與get_current_date，屬於多餘工具，可能增加Agent 的選擇複雜度","C":"ReAct 框架的核心問題在於Thought 步驟佔用過多token，應移除Thought 欄 位，直接讓Agent 輸出Action，以提升推理效率","D":"Agent 應在第一輪就呼叫所有可用工具並彙整結果，避免多輪Loop 造成的延 遲"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 66, 'iPAS 115年第1梯次中級 L21 公告試題，第16題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 16, 4, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-17', 'L21', 'official', '某醫療新創公司正在開發一套「多模態患者風險評估系統」，需同時處理三種異質 資料來源：胸腔X 光影像（影像模態）、臨床診斷筆記（文字模態），以及心率與 血氧的時序感測資料（數值時序模態）。工程師在進行各模態的特徵擷取模型選擇 時，需為每種模態挑選最適合的模型架構。下列哪一組模型配置最符合三種模態 各自的資料特性？', '{"A":"影像模態用LSTM、文字模態用CNN、時序模態用BERT","B":"影像模態用TF-IDF、文字模態用ResNet、時序模態用Word2Vec","C":"三種模態統一使用BERT，因為Transformer 架構具備通用性，可處理任意形 式的輸入資料","D":"影像模態用CNN、文字模態用Transformer、時序模態用LSTM 或Temporal CNN"}'::jsonb, array['L21101']::text[], 2, array['????', '115', '???']::text[], null, 67, 'iPAS 115年第1梯次中級 L21 公告試題，第17題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 17, 5, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-18', 'L21', 'official', '某醫院的AI 研究團隊正在開發一套整合「CT 影像+電子病歷文本+基因序列」三 種模態資料的癌症預測模型。請問在此場景中採用「跨模態對齊（Cross-Modal Alignment）」技術主要解決什麼問題？', '{"A":"使模型僅聚焦於CT 影像資料，避免文本與基因資料引入雜訊","B":"自動生成跨模態配對標註，以減少人工標記需求","C":"降低多模態資料的儲存與計算成本，以提升訓練效率","D":"將不同模態的資料表示對齊至共同語意空間，使模型能建立跨模態之間的語 意關聯"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 68, 'iPAS 115年第1梯次中級 L21 公告試題，第18題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 18, 6, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-19', 'L21', 'official', '一家電商公司已將推薦系統AI 模型上線三個月，業務主管要求專案團隊評估導 入成效。團隊根據下列圖表資料（AUC：尚無舊模型值，導入後為 0.91；CTR：3.2% 降至 3.1%；平均訂單金額：$850 提升至 $1,020；平均推論延遲：85 ms；每月推論費用：$12,000）得出結論：「因為AUC 高達0.91，模型表現優異，AI 導入成效良好。」請問此評估結論存在什麼根本問題？', '{"A":"僅依賴離線指標AUC 判斷模型成效，忽略線上業務指標（如 CTR 與營收） 的變化，可能導致錯誤結論","B":"AUC 已達0.91，代表模型排序能力優異，即使CTR 略為下降，仍可視為推薦 品質提升","C":"CTR 從3.2%降至3.1%，顯示模型效果變差，應立即還原（Rollback）至舊模 型","D":"平均訂單金額提升至$1,020，代表模型已成功優化營收，因此無需考慮其他指 標"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 69, 'iPAS 115年第1梯次中級 L21 公告試題，第19題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 19, 6, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-20', 'L21', 'official', '某電商公司計畫導入即時推薦系統，希望使用者進入網站後能在100 毫秒內取得推薦結果，且推薦結果需依據最新使用者行為進行調整。系統需支援每日約50 萬活躍使用者，尖峰時段每秒約3,000 筆請求（QPS）。目前公司已累積歷史購買紀錄與瀏覽行為資料，並持續接收即時點擊流（Streaming Data）。IT 基礎架構採用雲端環境，團隊配置為2 名資料工程師與1 名機器學習工程師。某工程師提出以下導入規劃：
(1)使用批次訓練（Batch Training）建立協同過濾模型
(2)將模型部署為REST API 提供即時推論服務
(3)使用Kafka 串流處理即時使用者行為特徵
(4)將所有即時資料先寫入資料倉儲（Data Warehouse）再進行特徵計算
(5)使用Redis 或Feature Store 快取即時特徵
請問以下哪一項最合理的技術導入規劃組合與調整建議？', '{"A":"保留(1)(2)(3)，移除(4)，並加入(5)以降低延遲","B":"保留(1)(4)，移除(3)，以確保資料一致性與系統穩定","C":"保留(2)(4)(5)，移除(1)，改用即時線上學習（Online Learning）","D":"全部保留(1)~(5)，可同時兼顧即時性與資料完整性"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 70, 'iPAS 115年第1梯次中級 L21 公告試題，第20題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 20, 6, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-21', 'L21', 'official', '一位機器學習工程師正在優化公司內部的RAG 法律文件問答系統。近期因營運 成本壓力，公司要求在不更換模型且不影響回答品質的前提下，將整體token 成 本降低至目前的60%，且目前成本主要集中於輸入tokens。工程師在檢查系統後， 盤點出目前的使用情況如下： ◆使用模型：GPT-4o（輸入$5／1M tokens、輸出 $15／1M tokens） ◆每次查詢：將前10 筆檢索文件區塊全部加入Prompt（每塊約600 tokens） ◆System Prompt：每次請求均包含約500tokens 的公司背景說明 ◆對話機制：保留完整對話歷史，平均累積約8,000tokens ◆每日查詢量：約5,000 次 ◆平均輸出：約300tokens／次 在上述限制與系統現況下，請問下列哪一項優化組合，最能在維持回答品質的前 提下有效降低token 成本？', '{"A":"將輸出max_tokens 從1,000 壓縮至200，強制模型給出更短的回答，以降低輸 出費用","B":"將System Prompt 改為Prompt Caching 或靜態前綴重用，並對對話歷史實作摘 要壓縮，以保留語意而非完整對話","C":"將所有查詢改為Batch API 模式送出，透過非同步處理降低單次費用","D":"在Prompt 中明確要求模型「回答時盡量簡短」，透過指令引導模型自行縮減輸 出長度"}'::jsonb, array['L21101']::text[], 2, array['????', '115', '???']::text[], null, 71, 'iPAS 115年第1梯次中級 L21 公告試題，第21題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 21, 7, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-22', 'L21', 'official', '某金融科技公司計劃建立完整的AI 開發到維運流程，希望實現「模型訓練→測試→部署→監控→再訓練」的自動化流程串接，並確保線上模型的版本可追溯。技術主管建議引入MLOps 框架。MLOps 在此AI 開發生命週期中的核心角色為何？', '{"A":"專注於訓練資料的標註與品質控管，以提升模型訓練效果","B":"透過自動化模型搜尋與參數調整，降低模型開發門檻","C":"建立機器學習流程的自動化與版本管理機制，支援模型部署、監控與持續更新","D":"確保模型在部署後維持穩定效能，減少後續維運與更新需求"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 72, 'iPAS 115年第1梯次中級 L21 公告試題，第22題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 22, 7, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-23', 'L21', 'official', '某製造業公司計劃將AI 導入生產線瑕疵檢測流程，目前瑕疵樣本約800 張（含 各類瑕疵類型）、正常樣本約15,000 張，現有IT 基礎設施為地端伺服器且無GPU， 且生產線環境需於地端即時完成推論，檢測需求為每片零件須在100 毫秒內完成 檢測，且預算為中等、無法於短期內大規模採購硬體。工程師正在規劃第一階段 的AI 導入方案，請問下列哪一種規劃最為合適？', '{"A":"從零訓練一個大型CNN 模型，並採購高階GPU 伺服器以滿足推論速度需求","B":"採用預訓練模型進行Transfer Learning，針對瑕疵樣本進行Fine-tuning，並使 用模型量化（Quantization）或蒸餾（Distillation）技術壓縮模型以符合延遲需求， 部署於地端","C":"因樣本數不足，建議先暫緩AI 導入，待蒐集至少10 萬筆瑕疵樣本後再啟動 專案","D":"將所有影像上傳至雲端，使用第三方AutoML 平台自動訓練並部署，以節省開 發時間"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 73, 'iPAS 115年第1梯次中級 L21 公告試題，第23題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 23, 8, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-24', 'L21', 'official', '某即時詐欺偵測系統對模型回應時間有嚴格限制，若推論延遲過高將影響交易核 准流程。維運工程師在模型上線前進行延遲測試（Latency Testing）時，主要評估 的目標為何？', '{"A":"評估模型推論過程中的記憶體使用量，以確認部署資源是否足夠","B":"驗證模型對異常或攻擊輸入的穩定性與安全性","C":"評估模型在不同使用者族群上的預測結果是否一致","D":"評估模型從接收輸入到產生預測結果所需的回應時間是否符合系統要求"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 74, 'iPAS 115年第1梯次中級 L21 公告試題，第24題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 24, 8, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-25', 'L21', 'official', '某企業欲將其AI 輔助決策系統提交給外部稽核單位審查，並宣稱符合NIST《AI 風險管理框架》（NIST AI RMF）中可驗證性（Verifiability）的要求。為讓第三方 稽核人員能獨立重現模型評估結果，下列哪一項技術實踐最直接符合此要求？', '{"A":"將模型測試準確率優化至99%以上，以達到業界公認的高可靠標準","B":"建立可追溯的測試資料與評估流程，並記錄模型訓練與評估過程中的關鍵設 定，以確保結果可被重現","C":"加快模型迭代速度，縮短版本發布週期以盡快累積外部驗證數據","D":"擴充訓練資料量至數百萬筆，以統計方式確保模型的泛化能力達標"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 75, 'iPAS 115年第1梯次中級 L21 公告試題，第25題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 25, 8, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-26', 'L21', 'official', '某銀行導入一套AI 授信審核系統，針對貸款申請人進行自動化決策。監理單位要求系統必須符合負責任AI（Responsible AI）原則，特別是對被拒絕的申請人提供每筆決策的具體理由說明。從技術與合規的角度，此要求的核心能力需求為何？', '{"A":"系統必須在收到申請後10 秒內自動刪除申請人個資","B":"系統應隨機調整部分決策以確保多元性","C":"系統必須保證所有決策準確率達到100%","D":"系統必須具備可解釋性（Explainability）能力，能提供特徵貢獻說明"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 76, 'iPAS 115年第1梯次中級 L21 公告試題，第26題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 26, 8, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-27', 'L21', 'official', '某醫院計劃導入一套AI 醫療影像診斷輔助系統，用於輔助放射科醫師判讀CT 影 像。院方技術委員會討論在人命攸關且需確保最終臨床決策責任由人類承擔的情 境下，從系統設計架構層面，最關鍵的安全機制為何？', '{"A":"採用人機協作（Human-in-the-Loop, HITL）架構，由醫師最終審核決策","B":"模型信心低於閾值（Threshold）即自動關機","C":"隨機切換模型並以多數決決策","D":"對輸入影像加入隨機擾動"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 77, 'iPAS 115年第1梯次中級 L21 公告試題，第27題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 27, 9, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-28', 'L21', 'official', '一位資料科學家使用XGBoost 建立信用風險評分模型，並使用SHAP 解釋模型 對某申請人的預測結果。SHAP summary plot 顯示該樣本中「月收入」的SHAP 值 為-2.3，「負債比率」為+1.8，其中SHAP 值代表各特徵對模型輸出值的影響程度 與方向。關於對SHAP 值的解讀，下列敘述何者正確？', '{"A":"「月收入」的SHAP 值-2.3 代表該特徵使此申請人的違約預測機率降低了2.3%","B":"「月收入」的SHAP 值-2.3 代表相對於基準值（base value），此特徵將模型輸 出值往負方向推移了2.3 個單位，表示月收入對該申請人有降低違約風險的貢獻","C":"SHAP 值為負代表該特徵對模型整體來說是不重要的特徵，應考慮從模型中移 除","D":"負債比率」SHAP 值+1.8 代表負債比率是整個訓練集中對違約影響最大的特徵"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 78, 'iPAS 115年第1梯次中級 L21 公告試題，第28題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 28, 9, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-29', 'L21', 'official', '某工程師為一套卷積神經網路（CNN）的醫療影像輔助診斷系統設計模型可解釋 性機制。該系統需滿足下列需求： 1.能向醫師說明影像被判定為異常的原因 2.支援近即時推論，每次解釋須於200 毫秒內完成，且不可進行大量重複採樣計 算 3.解釋結果須以影像中具代表性的視覺化像素區域呈現 在此情境下，下列何種方法最為適合？', '{"A":"使用LIME，透過超像素擾動取樣分析影像區塊對預測的影響","B":"使用SHAP KernelExplainer，計算各像素的Shapley 值並疊加於原始影像","C":"使用Grad-CAM（Class Activation Map），透過梯度反向傳播生成類別關注區域；","D":"使用SHAP TreeExplainer，計算特徵貢獻並以熱力圖呈現"}'::jsonb, array['L21101']::text[], 2, array['????', '115', '???']::text[], null, 79, 'iPAS 115年第1梯次中級 L21 公告試題，第29題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 29, 9, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-30', 'L21', 'official', '某資料科學家正在處理一份包含200 個感測器特徵的工廠設備監測資料集，為了 降低模型複雜度並保留主要變異資訊，他先對資料進行標準化（Standardization）， 再使用主成分分析（PCA）進行降維。在PCA 過程中，為了找出能最大化資料變 異量的主成分方向，演算法主要依賴哪一項數學操作？', '{"A":"透過對目標函數進行梯度下降（Gradient Descent）最佳化，迭代求得主成分方 向","B":"根據特徵與目標變數之間的相關性（Correlation）進行排序，選擇重要特徵","C":"對資料的協方差矩陣（Covariance Matrix ）進行特徵值分解（Eigen Decomposition），取得對應主要變異方向的特徵向量","D":"對資料矩陣進行卷積運算（Convolution），擷取特徵之間的局部關係"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 80, 'iPAS 115年第1梯次中級 L21 公告試題，第30題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 30, 10, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-31', 'L21', 'official', '某資料工程師嘗試對包含300 個特徵的使用者行為資料集使用DBSCAN 進行群 集分析，但發現幾乎所有資料點都被判定為雜訊點（Noise Points），難以形成有 意義的群集，即使不斷調整ε（Epsilon）與MinPts 參數也無濟於事。請問下列何 者為此問題最可能的根本原因？', '{"A":"在高維空間中，維度詛咒（Curse of Dimensionality）使得資料點之間的距離趨 於相近，導致DBSCAN 的密度估計失效","B":"DBSCAN 演算法僅適用於低維資料，無法處理高維資料","C":"300 個特徵的資料必然不具備群集結構，因此無法進行有效的分群","D":"高維空間中核心點的數量會受到數學限制，導致無法形成群集"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 81, 'iPAS 115年第1梯次中級 L21 公告試題，第31題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 31, 10, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-32', 'L21', 'official', '某工程師正在實作一個CNN 影像分類模型，在PyTorch 中定義模型架構時，需 要在卷積擷取特徵後接上全連結層（Fully Connected Layer）進行分類。在模型程 式碼中，需要在卷積輸出與全連結層之間插入什麼操作？', '{"A":"使用全域平均池化（Global Average Pooling）將特徵圖壓縮後再接全連結層","B":"使用Flatten 將特徵圖展平成一維向量","C":"直接將卷積輸出接到全連結層，系統會自動轉換維度","D":"先對特徵圖做Softmax，再輸入全連結層"}'::jsonb, array['L21101']::text[], 2, array['????', '115', '???']::text[], null, 82, 'iPAS 115年第1梯次中級 L21 公告試題，第32題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 32, 10, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-33', 'L21', 'official', '某自駕車公司的AI 訓練團隊面臨標註成本高的問題，無法取得足夠的真實惡劣 天氣（大雨、濃霧）駕駛場景資料，工程師提議使用合成資料（Synthetic Data） 來補充訓練集。請問下列何者最能正確敘述合成資料在AI 訓練中的角色？', '{"A":"合成資料主要用於文字任務的資料擴增，影像任務仍需依賴真實資料","B":"合成資料可完全取代真實資料，直接用於模型訓練","C":"合成資料主要用於降低模型推論時的計算成本","D":"合成資料可在控制條件下產生多樣化場景，用於擴充訓練資料並提升模型的泛化能力"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 83, 'iPAS 115年第1梯次中級 L21 公告試題，第33題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 33, 10, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-34', 'L21', 'official', '某廣告技術公司的點擊率（CTR）預測系統每天新增數百個用戶行為特徵（如新 廣告位、新設備類型），特徵空間持續動態擴展。若採用傳統靜態模型每週批次重 訓一次，會導致嚴重的模型過期問題。為在特徵空間頻繁變化的情況下維持模型 即時準確度，最適合的模型架構方向為何？', '{"A":"採用傳統靜態羅吉斯迴歸（Logistic Regression），縮短批次重訓週期從每週改 為每日","B":"採用支援增量學習（Incremental Learning）的模型，使模型能隨新資料即時更 新並適應新增特徵，而不需重新訓練整個模型","C":"採用固定架構的深度神經網路（DNN），每次有新特徵時重新定義輸入層後全 量重訓","D":"改用預訓練圖神經網路（GNN），透過圖結構建立特徵間的關聯，自動應對新 增特徵"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 84, 'iPAS 115年第1梯次中級 L21 公告試題，第34題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 34, 11, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-35', 'L21', 'official', '某生物醫學研究機構正在建構一個整合「基因序列特徵」與「電子病歷文本特徵」 的疾病風險預測模型。由於高維數值特徵和語意文本特徵的性質差異顯著，請問 下列哪一種特徵處理與選擇策略最為合適？', '{"A":"將所有特徵合併為單一特徵矩陣後，使用主成分分析（PCA）進行降維，作為 模型輸入","B":"採分層策略，先對基因序列特徵進行特徵選擇，再對文本特徵進行語意表示， 最後將兩類特徵融合（Feature Fusion）後輸入模型","C":"將所有特徵合併後，使用隨機森林（Random Forest）的特徵重要性進行一次性 排序與篩選","D":"將文本特徵轉換為簡單統計特徵（如詞頻）後與基因特徵一併建模，以降低特 徵處理複雜度"}'::jsonb, array['L21104']::text[], 2, array['????', '115', '???']::text[], null, 85, 'iPAS 115年第1梯次中級 L21 公告試題，第35題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 35, 11, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-36', 'L21', 'official', '某公司希望開發一個工業零件瑕疵辨識分類模型，共有10 個類別，但每類僅約 50 張人工標註影像（總計約500 張）。由於標註成本高昂，短期內無法擴充資料 集。在此情境下，工程師需要在有限標註資料下建構高效能模型。請問下列哪一 種策略最為適合？', '{"A":"使用在大型資料集預訓練完成的卷積神經網路（CNN），並進行遷移學習微調","B":"從頭訓練大型 Vision Transformer（ViT），完全使用現有500 張影像","C":"使用K-means 對影像進行分群，並直接將群集結果作為分類模型輸出","D":"複製既有的資料以增加標註影像數量，並從頭訓練深度CNN 模型"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 86, 'iPAS 115年第1梯次中級 L21 公告試題，第36題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 36, 11, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-37', 'L21', 'official', '某製造廠開發產線瑕疵檢測模型時，資料集存在嚴重類別不平衡問題，其中良品約占99%，瑕疵品僅占1%。若直接使用原始資料進行訓練，模型容易偏向預測多數類別（良品），導致對少數類別（瑕疵品）辨識能力不足。在不調整模型架構與學習演算法的前提下，僅透過資料前處理方式改善此問題，下列何者最適當？', '{"A":"使用SMOTE 等過採樣方法進行少數類別擴增","B":"加入L1／L2 正則化（Regularization）以防止過擬合","C":"大幅增加深度神經網路的層數，以強化特徵萃取能力","D":"複製更多良品數據，以進一步提升模型的準確率（Accuracy）"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 87, 'iPAS 115年第1梯次中級 L21 公告試題，第37題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 37, 11, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-38', 'L21', 'official', '某IoT 平台接收工廠溫度感測器資料，發現在常態分佈（均值25°C，標準差2° C）的數萬筆紀錄中，出現數筆「999°C」的極端值，研判為感測器通訊錯誤（網 路封包延遲導致數值溢位）所致，且該異常數值在實際情況下不可能發生。在進 行模型訓練前的資料清洗階段，針對這類離群值，最適當的處理策略為何？', '{"A":"保留所有原始數值，並使用平均數（Mean）作為特徵輸入模型","B":"對數據進行Z-score 標準化，使數值落於約[-3, 3]範圍","C":"將999°C 以獨熱編碼（One-Hot Encoding）轉為獨立類別特徵","D":"刪除異常的999°C 記錄，或以中位數（Median）進行填補"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 88, 'iPAS 115年第1梯次中級 L21 公告試題，第38題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 38, 12, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-39', 'L21', 'official', '某AI 平台工程師正在為多模態模型訓練系統規劃資料儲存架構，需要同時處理 原始影像、非結構化文本，以及經過整理的結構化特徵資料。在此情境下，應如 何選擇資料湖（Data Lake）與資料倉儲（Data Warehouse）的使用方式？', '{"A":"將原始影像與文本資料儲存在Data Lake，將整理後的結構化特徵資料儲存在 Data Warehouse","B":"將所有資料統一儲存在Data Warehouse，以提升查詢效率","C":"將所有資料統一儲存在Data Lake，但犧牲結構化資料的查詢效率","D":"僅將原始影像資料儲存在Data Lake，其餘資料統一存入Data Warehouse"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 89, 'iPAS 115年第1梯次中級 L21 公告試題，第39題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 39, 12, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-40', 'L21', 'official', '某智慧製造公司在產線上部署工業相機進行即時外觀瑕疵檢測，原先將影像傳至 雲端進行AI 推論，但因網路延遲與連線不穩導致系統無法滿足即時需求（需低 於200ms）。工程師因此改為將模型部署於產線端的邊緣裝置後，但仍未達系統需 求。在不更換硬體設備的前提下，下列哪一組技術最能有效降低推論延遲，同時 維持合理準確率？', '{"A":"減少訓練資料的使用數量，並重新訓練模型以提升推論效率","B":"使用批次推論（Batch Inference）處理多張影像以提升計算效率","C":"採用模型集成（Model Ensemble），透過多模型投票提升準確率","D":"將模型由FP32 量化為INT8，並進行推論加速優化"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 90, 'iPAS 115年第1梯次中級 L21 公告試題，第40題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 40, 12, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-41', 'L21', 'official', '某AI 影像辨識平台以單一GPU 伺服器提供多租戶推論服務，系統長期觀察到GPU 使用率約維持在60%左右，且在執行過程中可觀察到GPU kernel 之間存在明顯閒置間隔，單次推論多以小批次方式執行。然而，在尖峰時段時，請求延遲會出現明顯波動甚至突增。同時，CPU 與記憶體資源使用率均未達瓶頸，且系統團隊已排除硬體、網路與請求併發控制異常。在此情境下，請判斷最可能造成問題的原因為何？', '{"A":"GPU 排程策略與批次大小設定不當，導致GPU 運算單元未被有效利用","B":"請求併發控制機制不佳，導致多個請求同時搶占GPU Context 資源造成延遲","C":"GPU 硬體效能不足，無法支撐推論負載","D":"模型未進行量化優化，導致推論計算成本過高"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 91, 'iPAS 115年第1梯次中級 L21 公告試題，第41題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 41, 12, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-42', 'L21', 'official', '某保險公司將理賠金額預測模型正式部署上線，MLOps 團隊設計監控機制。三個 月後模型整體均方根誤差（RMSE）無明顯變化，但業務單位反映高額理賠案件 的預測誤差明顯增加。經分析，高額理賠案件僅佔約5%的樣本比例，且未被監 控機制及時發現。請問最可能的設計缺陷為何？', '{"A":"監控頻率不足，應由每日批次監控改為即時串流監控","B":"高額理賠案件屬於長尾分布，難以透過監控指標偵測，因此無法透過監控機制 發現問題","C":"RMSE 無法有效反映高額誤差，應改以平均絕對誤差（MAE）作為主要監控指 標","D":"僅監控整體RMSE，未針對不同理賠金額區間進行分群監控"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 92, 'iPAS 115年第1梯次中級 L21 公告試題，第42題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 42, 13, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-43', 'L21', 'official', '某電商平台的演算法工程師開發了一個新版商品推薦模型，在離線A/B 測試中， 新模型的各項評估指標（AUC、NDCG@10）均顯著優於現行線上模型。然而， 離線測試無法完全反映真實使用者的互動行為（點擊、購買、停留時間）。在正式 全面上線前，若希望在可控制風險下量化真實業務指標，應採用下列何種線上驗 證策略？', '{"A":"影子模式（Shadow Mode）：新舊模型同時產生預測，但僅顯示舊模型結果， 於後端比較輸出差異","B":"回測（Backtesting）：使用歷史日誌模擬模型表現作為上線依據","C":"金絲雀發布（Canary Release）：將1–5%使用者流量導向新模型，量測CTR、 CVR 等指標並逐步擴量","D":"負載測試（Load Testing）：於測試環境進行高流量壓力測試後直接全面上線"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 93, 'iPAS 115年第1梯次中級 L21 公告試題，第43題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 43, 13, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-44', 'L21', 'official', '某MLOps 工程師正在設計AI 模型的推論服務API，需要處理使用者上傳的高解 析度影像（平均5MB）進行即時分類。在RESTful API 設計時，選擇HTTP 請求 方法與資料傳輸格式的最佳實踐為何？', '{"A":"使用HTTP GET 方法，將影像資料 Base64 編碼後附加於URL Query String 中","B":"採用HTTP POST 請求，將影像資料以multipart/form-data 或application/octet-stream 傳輸於Request Body","C":"使用HTTP PUT 方法，透過Content-Type: application/xml 傳遞影像資料","D":"要求客戶端下載模型於本地推論，僅回傳分類結果"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 94, 'iPAS 115年第1梯次中級 L21 公告試題，第44題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 44, 13, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-45', 'L21', 'official', '某AI 平台整合多個外部AI 微服務（語音辨識API、NLP 分析API、知識圖譜查 詢服務），在高峰期間某外部服務偶發延遲或逾時（Timeout），導致請求鏈路壅塞， 最終造成平台級服務中斷（Cascading Failure）。為從架構層面預防此類連鎖故障， 最有效的設計模式為何？', '{"A":"將所有外部API 呼叫改為同步串行處理，並取消逾時限制，確保每個請求皆 完成後再繼續","B":"為外部服務導入斷路器模式（Circuit Breaker），在異常時暫停呼叫並提供替代 回應","C":"擴充各微服務的執行緒池（Thread Pool）上限，以提升併發處理能力","D":"停用服務健康檢查，減少不必要的額外負載"}'::jsonb, array['L21101']::text[], 2, array['????', '115', '???']::text[], null, 95, 'iPAS 115年第1梯次中級 L21 公告試題，第45題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 45, 14, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-46', 'L21', 'official', '某醫院計劃建立混合雲AI 平台：使用公有雲GPU 叢集進行CT 影像模型訓練， 但基於HIPAA（Health Insurance Portability and Accountability Act）法規要求，患 者影像原始資料不得離開醫院院內環境。下列何者最符合「利用公有雲算力訓練 模型」與「不傳輸原始患者資料」雙重限制的技術方案？', '{"A":"將患者影像資料以AES-256 加密後上傳至公有雲，並於雲端解密後進行模型 訓練","B":"在院內部署同態加密（Homomorphic Encryption）模組，對推論請求進行加密 處理","C":"採用聯邦學習（Federated Learning）於院內訓練模型，僅傳送模型更新至雲端 聚合，原始資料不外流","D":"建立專線VPN 連接醫院與雲端，以網路層安全保護資料傳輸"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 96, 'iPAS 115年第1梯次中級 L21 公告試題，第46題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 46, 14, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-47', 'L21', 'official', '某電商平台將新的推薦模型部署至線上系統，為降低風險，團隊採用漸進式部署 策略（Phased Rollout），先將新模型流量從5%逐步提升至100%。在部署初期， 團隊發現轉換率（Conversion Rate）略有提升，但在流量提升至30%時，系統延 遲（Latency）明顯上升，且部分使用者體驗變差。請問在此情境下，最適當的下 一步策略為何？', '{"A":"立即將新模型全面部署至100%，以觀察整體效果並評估系統表現變化","B":"還原（Rollback）至舊模型並停止新模型測試流程，以確保系統穩定與使用者 體驗品質","C":"維持目前30%流量並持續觀察，即使延遲問題存在也暫不進行調整","D":"暫停流量提升，針對延遲問題進行效能分析與優化後再繼續部署"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 97, 'iPAS 115年第1梯次中級 L21 公告試題，第47題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 47, 14, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-48', 'L21', 'official', '某銀行的信用卡風控模型已穩定上線一年，主要用於偵測盜刷交易提醒。近期在 未對模型或特徵工程進行調整的情況下，系統觀察到深夜電商交易的核准率明顯 上升，盜刷攔截率下降，但模型AUC 幾乎維持不變，且交易金額、地區與裝置 等特徵分布未出現明顯變化。進一步分析發現，疫情後使用者行為改變，使原本 被視為高風險的交易型態逐漸轉為一般消費。下列何者最能敘述此現象的原因？', '{"A":"資料漂移（Data Drift），因輸入特徵分布發生變化","B":"訓練與服務偏差（Training-Serving Skew），因線上與離線特徵處理不一致","C":"概念漂移（Concept Drift），因特徵與目標標籤之間的關聯性改變","D":"決策閾值偏移（Threshold Shift），因分類門檻設定不當導致預測偏差"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 98, 'iPAS 115年第1梯次中級 L21 公告試題，第48題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 48, 15, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-49', 'L21', 'official', '某零售電商平台已建立模型監控儀表板，用於追蹤線上推薦模型的運作狀態與效 能表現。維運工程師需判斷哪些指標屬於「線上持續監控（Continuous Monitoring）」的範疇。下列指標中，哪一項最不適合在即時監控系統中追蹤，而 應改由離線實驗追蹤系統管理？', '{"A":"訓練實驗中每個Epoch 的學習率（Learning Rate）變化曲線與超參數 （Hyperparameter）設定軌跡","B":"線上推論API 的P50/P95/P99 回應延遲與每日請求量（RPS）趨勢","C":"輸入特徵分佈的族群穩定性指數（Population Stability Index, PSI），偵測資料漂 移","D":"模型預測結果分佈（如CTR）與定期回收的人工標註結果之對比"}'::jsonb, array['L21301']::text[], 2, array['????', '115', '???']::text[], null, 99, 'iPAS 115年第1梯次中級 L21 公告試題，第49題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 49, 15, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-official-115-50', 'L21', 'official', '某醫療團隊建立肺炎診斷系統，採用晚期融合（Late Fusion）策略，將胸腔X 光 影像與病患問診文字分別進行預測後再整合結果。測試發現，當問診紀錄品質不 佳（如描述簡短或資訊缺漏）時，整體模型效能僅小幅下降。關於此現象，下列 何者最不可能為其原因？', '{"A":"各模態獨立進行預測，可降低單一模態品質不佳對整體結果的影響","B":"融合階段可調整不同模態的權重，使低品質模態影響降低","C":"各模態使用獨立模型，使錯誤不會在特徵層被放大","D":"晚期融合會在輸入階段整合多模態特徵，因此能避免低品質資料影響"}'::jsonb, array['L21104']::text[], 2, array['????', '115', '???']::text[], null, 100, 'iPAS 115年第1梯次中級 L21 公告試題，第50題', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', 115, '1', 50, 15, null, '[{"title":"iPAS 官方學習資源頁","url":"https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources","published":"accessed 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-01-1', 'L21', 'exam_style', '客服語料常出現訓練詞彙表未收錄的新詞。團隊希望把未知詞拆成已知子詞元，降低整詞變成未知符號的情況；最符合此需求的是？', '{"A":"僅依完整詞頻建立 one-hot 向量","B":"採用子詞元 tokenizer，依模型詞彙切分未知詞","C":"將每個未知詞都改寫成英文翻譯","D":"刪除所有未見詞所在句子"}'::jsonb, array['L21101']::text[], 2, array['自編', '仿歷屆題型', 'WordPiece 子詞切分']::text[], null, 102, '自編仿題：L21 自然語言處理技術與應用（WordPiece 子詞切分）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-01-2', 'L21', 'exam_style', '文件摘要系統需要判斷「林小姐交付報告給王先生後，她離開了」中的「她」指向誰。此處需要的 NLP 能力是？', '{"A":"情感分析，判斷句子正負面","B":"文字分類，將整份文件分到主題類別","C":"共指消解，連結代名詞與其所指實體","D":"詞性標註，只找出名詞和動詞"}'::jsonb, array['L21101']::text[], 2, array['自編', '仿歷屆題型', '共指消解']::text[], null, 104, '自編仿題：L21 自然語言處理技術與應用（共指消解）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-01-3', 'L21', 'exam_style', '法規資料庫需縮短長文件，但要求摘要句子必須直接出自原文。較符合此限制的摘要方式是？', '{"A":"抽象式摘要，重新生成原文未出現的句子","B":"機器翻譯，改用另一種語言","C":"命名實體辨識，只輸出人名","D":"抽取式摘要，選取原文中的重要句子"}'::jsonb, array['L21101']::text[], 2, array['自編', '仿歷屆題型', '抽取式摘要']::text[], null, 106, '自編仿題：L21 自然語言處理技術與應用（抽取式摘要）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-01-4', 'L21', 'exam_style', '入口服務收到中、英、日混合的使用者訊息，需先選擇後續處理模型。最直接的前置任務是？', '{"A":"語言識別，估計輸入文字使用的語言","B":"NER，辨識文字中的人名和地點","C":"情感分析，判定情緒標籤","D":"語音合成，產生音訊"}'::jsonb, array['L21101']::text[], 2, array['自編', '仿歷屆題型', '語言識別']::text[], null, 108, '自編仿題：L21 自然語言處理技術與應用（語言識別）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-01-5', 'L21', 'exam_style', '客服中心要將通話音訊轉成逐字稿供搜尋，系統輸入是語音、輸出是文字。應選擇哪種任務？', '{"A":"文件摘要","B":"自動語音辨識（ASR）","C":"文字轉語音（TTS）","D":"文本情感分類"}'::jsonb, array['L21101']::text[], 2, array['自編', '仿歷屆題型', '語音辨識與文字轉錄']::text[], null, 110, '自編仿題：L21 自然語言處理技術與應用（語音辨識與文字轉錄）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-02-1', 'L21', 'exam_style', '無障礙服務要把網頁文字朗讀成語音，最直接使用哪種技術？', '{"A":"命名實體辨識","B":"詞向量相似度","C":"文字轉語音（TTS）","D":"自動語音辨識（ASR）"}'::jsonb, array['L21101']::text[], 2, array['自編', '仿歷屆題型', '文字轉語音']::text[], null, 112, '自編仿題：L21 自然語言處理技術與應用（文字轉語音）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-02-2', 'L21', 'exam_style', '物流中心要從包裹照片擷取印刷地址，並輸出可搜尋文字。最直接的視覺任務是？', '{"A":"影像分類，只判定包裹類別","B":"物件追蹤，連結影片中物件","C":"影像去噪，只降低畫面雜訊","D":"光學字元辨識（OCR）"}'::jsonb, array['L21102']::text[], 2, array['自編', '仿歷屆題型', 'OCR 文字擷取']::text[], null, 114, '自編仿題：L21 電腦視覺技術與應用（OCR 文字擷取）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-02-3', 'L21', 'exam_style', '相簿服務要判定每張照片是否含有海灘場景，不要求回報場景位置。最符合需求的是？', '{"A":"整張影像分類","B":"物件偵測並輸出每個物件框","C":"語意分割並逐像素標色","D":"影片追蹤並計算跨影格軌跡"}'::jsonb, array['L21102']::text[], 2, array['自編', '仿歷屆題型', '影像分類標籤']::text[], null, 116, '自編仿題：L21 電腦視覺技術與應用（影像分類標籤）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-02-4', 'L21', 'exam_style', '訓練影像分類器時樣本有限，團隊考慮隨機水平翻轉。採用前最重要的判斷是？', '{"A":"只增加影像檔案尺寸而不改變內容","B":"確認該轉換不改變任務標籤語意，再只用於訓練流程","C":"把驗證集和測試集也大量翻轉後併入訓練","D":"隨機更換每張影像的標籤"}'::jsonb, array['L21102']::text[], 2, array['自編', '仿歷屆題型', '影像資料增強']::text[], null, 118, '自編仿題：L21 電腦視覺技術與應用（影像資料增強）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-02-5', 'L21', 'exam_style', '工廠只有少量已標註瑕疵影像，卻可使用相近影像任務的預訓練模型。常見的起始策略是？', '{"A":"將測試影像複製到訓練集","B":"直接使用預訓練模型輸出並宣稱已符合新任務","C":"以預訓練權重初始化，再依新資料評估凍結或微調","D":"從隨機權重訓練且禁止使用驗證集"}'::jsonb, array['L21102']::text[], 2, array['自編', '仿歷屆題型', '預訓練模型遷移']::text[], null, 120, '自編仿題：L21 電腦視覺技術與應用（預訓練模型遷移）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-03-1', 'L21', 'exam_style', '偵測器對同一個行李箱輸出多個高度重疊的候選框。常見後處理會如何減少重複框？', '{"A":"把所有框平均成一個類別標籤","B":"隨機刪除最高信心框","C":"將候選框轉成語意分割遮罩","D":"依信心排序保留候選框，並抑制與高分框重疊過高的框"}'::jsonb, array['L21102']::text[], 2, array['自編', '仿歷屆題型', '非極大值抑制']::text[], null, 122, '自編仿題：L21 電腦視覺技術與應用（非極大值抑制）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-03-2', 'L21', 'exam_style', '監控影片要持續識別每一影格中行人，並估計同一人的移動軌跡。此需求相較單張影像偵測多出哪項任務？', '{"A":"在連續影格間維持物件身分關聯","B":"只對整段影片給一個場景類別","C":"為每個像素做一次語意標註即可得到身分","D":"將影片壓縮成單張照片"}'::jsonb, array['L21102']::text[], 2, array['自編', '仿歷屆題型', '影片物件追蹤']::text[], null, 124, '自編仿題：L21 電腦視覺技術與應用（影片物件追蹤）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-03-3', 'L21', 'exam_style', '設計合成瑕疵影像的 GAN 訓練流程時，兩個網路的典型分工為何？', '{"A":"判別器負責把文字翻譯成影像，生成器計算準確率","B":"生成器產生樣本以欺騙判別器，判別器學習區分真實與生成樣本","C":"生成器只標註資料，判別器只清除重複檔案","D":"兩者都固定不更新參數"}'::jsonb, array['L21103']::text[], 2, array['自編', '仿歷屆題型', 'GAN 對抗目標']::text[], null, 126, '自編仿題：L21 生成式 AI 技術與應用（GAN 對抗目標）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-03-4', 'L21', 'exam_style', '影像生成團隊採用去噪擴散模型。模型在生成時通常如何從隨機初始狀態形成影像？', '{"A":"以分類器逐像素輸出固定標籤","B":"一次將所有噪聲設為平均像素","C":"依學得的反向去噪步驟逐步將噪聲轉成樣本","D":"直接從資料庫複製最相似訓練影像"}'::jsonb, array['L21103']::text[], 2, array['自編', '仿歷屆題型', '擴散模型反向生成']::text[], null, 128, '自編仿題：L21 生成式 AI 技術與應用（擴散模型反向生成）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-03-5', 'L21', 'exam_style', '文字生成系統採 nucleus sampling。Top-p 的候選集合如何形成？', '{"A":"永遠只選最高機率的一個 token","B":"固定保留字典中編號最小的 p 個 token","C":"將所有 token 機率改成相同值","D":"依 token 機率由高至低累加，取達到指定累積機率的最小集合再抽樣"}'::jsonb, array['L21103']::text[], 2, array['自編', '仿歷屆題型', 'Top-p 取樣']::text[], null, 130, '自編仿題：L21 生成式 AI 技術與應用（Top-p 取樣）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-04-1', 'L21', 'exam_style', '團隊需調整大型語言模型的任務行為，但 GPU 記憶體有限。LoRA 常見做法為何？', '{"A":"凍結多數原權重，訓練低秩更新參數以減少可訓練參數量","B":"每次訓練都從頭更新所有原模型權重","C":"只在提示中增加文字且不訓練任何參數","D":"刪除模型所有注意力層"}'::jsonb, array['L21103']::text[], 2, array['自編', '仿歷屆題型', 'LoRA 參數高效微調']::text[], null, 132, '自編仿題：L21 生成式 AI 技術與應用（LoRA 參數高效微調）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-04-2', 'L21', 'exam_style', '文件助理可透過工具讀取內部資料。上傳文件含有要求模型外傳機密的指令，哪項防護最重要？', '{"A":"只在提示中寫一次「不要洩漏」便視為完成防護","B":"把文件視為不可信輸入並以權限控制、動作驗證限制工具呼叫","C":"讓文件指令覆蓋系統政策","D":"把所有工具設為最高權限，依賴模型自行判斷"}'::jsonb, array['L21103']::text[], 2, array['自編', '仿歷屆題型', '不可信提示與工具權限']::text[], null, 134, '自編仿題：L21 生成式 AI 技術與應用（不可信提示與工具權限）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-04-3', 'L21', 'exam_style', '研究人員要比較兩個提示模板，但每次生成都使用不同隨機性，結果難以歸因。較好的實驗設計是？', '{"A":"改變模型與提示後仍把差異歸因於提示","B":"把所有生成結果人工改成相同文字","C":"固定可控制的生成參數與種子，並重複多次報告變異","D":"只保留最符合假設的一次輸出"}'::jsonb, array['L21103']::text[], 2, array['自編', '仿歷屆題型', '推論重現性與隨機種子']::text[], null, 136, '自編仿題：L21 生成式 AI 技術與應用（推論重現性與隨機種子）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-04-4', 'L21', 'exam_style', '長影片視覺問答成本過高，團隊考慮降低送入模型的影格頻率。調整時應優先評估什麼？', '{"A":"只比較輸入影片檔名","B":"把每個影格都改成相同影像以降低成本","C":"只看平均亮度是否改變","D":"事件持續時間與取樣間隔，確認關鍵短暫動作不會被漏掉"}'::jsonb, array['L21104']::text[], 2, array['自編', '仿歷屆題型', '影片取樣率取捨']::text[], null, 138, '自編仿題：L21 多模態人工智慧應用（影片取樣率取捨）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-04-5', 'L21', 'exam_style', '兩個感測器各自訓練分類器，最後將兩個分類分數加權整合。這種融合位置通常稱為？', '{"A":"決策層或晚期融合","B":"輸入像素級早期融合","C":"單模態預測","D":"資料標註仲裁"}'::jsonb, array['L21104']::text[], 2, array['自編', '仿歷屆題型', '決策層晚期融合']::text[], null, 140, '自編仿題：L21 多模態人工智慧應用（決策層晚期融合）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題的情境式單選結構；題目與選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-05-1', 'L21', 'exam_style', '故障分類先編碼影像和感測值，再合併特徵向量共同分類，屬於哪種融合？', '{"A":"資料標註仲裁","B":"特徵層早期融合","C":"預測後整合分數的晚期融合","D":"單模態分類"}'::jsonb, array['L21104']::text[], 2, array['自編', '仿歷屆題型', '早期特徵融合']::text[], null, 142, '自編仿題：L21 多模態人工智慧應用（早期特徵融合）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-05-2', 'L21', 'exam_style', '使用者問「桌上有幾個杯子？」系統需依照片回答。模型應結合什麼？', '{"A":"只依影像檔名","B":"只看訓練集答案頻率","C":"問題文字語意與當前影像證據","D":"只依問題文字推測常見數量"}'::jsonb, array['L21104']::text[], 2, array['自編', '仿歷屆題型', '視覺問答證據']::text[], null, 144, '自編仿題：L21 多模態人工智慧應用（視覺問答證據）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-05-3', 'L21', 'exam_style', '機器人要把深度相機中的障礙物座標映射至機械手臂座標。融合前需先做什麼？', '{"A":"隨機配對影像和座標","B":"將所有座標除以任意常數","C":"只依檔名排序","D":"校正感測器並轉換至共同座標系"}'::jsonb, array['L21104']::text[], 2, array['自編', '仿歷屆題型', '空間座標校正']::text[], null, 146, '自編仿題：L21 多模態人工智慧應用（空間座標校正）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-05-4', 'L21', 'exam_style', '多模態客服系統某次語音很嘈雜，但文字輸入清楚。融合設計可如何減少噪音影響？', '{"A":"評估各模態品質，依可靠度調整權重或觸發降級處理","B":"所有模態永遠給相同固定權重","C":"刪除品質較好的文字輸入","D":"把音訊預測視為確定真值"}'::jsonb, array['L21104']::text[], 2, array['自編', '仿歷屆題型', '模態品質權重']::text[], null, 148, '自編仿題：L21 多模態人工智慧應用（模態品質權重）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-05-5', 'L21', 'exam_style', '倉庫延誤主要來自動線設計而非錯誤辨識。評估 AI 前應先做什麼？', '{"A":"把延誤全歸因於員工","B":"量測流程瓶頸並比較流程改善與 AI 能否解決成因","C":"直接訓練影像模型，因現場有相機","D":"只比較模型參數量"}'::jsonb, array['L21201']::text[], 2, array['自編', '仿歷屆題型', '流程瓶頸與方案適配']::text[], null, 150, '自編仿題：L21 AI 導入評估（流程瓶頸與方案適配）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-06-1', 'L21', 'exam_style', 'AI 草擬內部摘要與 AI 自動拒絕貸款，評估方法應有何差異？', '{"A":"摘要用途一律高風險、貸款用途一律低風險","B":"先採高影響用途增加資料","C":"依決策影響、錯誤後果與受影響者安排相稱的驗證及監督","D":"兩者風險相同，只看準確率"}'::jsonb, array['L21201']::text[], 2, array['自編', '仿歷屆題型', '用途影響分級']::text[], null, 152, '自編仿題：L21 AI 導入評估（用途影響分級）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-06-2', 'L21', 'exam_style', 'AI 將改變客服人員工作並影響顧客等待時間。需求盤點最完整的是？', '{"A":"只訪談預算核准者","B":"只問模型供應商","C":"只看開發者偏好的技術","D":"蒐集決策者、操作人員及受影響顧客的需求與影響"}'::jsonb, array['L21201']::text[], 2, array['自編', '仿歷屆題型', '利害關係人需求']::text[], null, 154, '自編仿題：L21 AI 導入評估（利害關係人需求）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-06-3', 'L21', 'exam_style', '審核人員需向客戶說明拒絕理由並可追溯。方案比較時需納入什麼？', '{"A":"能否提供符合用途的決策依據與紀錄","B":"只比較推論速度","C":"只選參數最多的模型","D":"只看生成文字是否流暢"}'::jsonb, array['L21201']::text[], 2, array['自編', '仿歷屆題型', '可解釋性需求選型']::text[], null, 156, '自編仿題：L21 AI 導入評估（可解釋性需求選型）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-06-4', 'L21', 'exam_style', 'AI 錯誤可能造成難以撤回的客戶權益損失。評估使用方式需優先考量？', '{"A":"只在年度報告記錄事故","B":"限制自動化範圍並設計覆核、申訴及補救機制","C":"只提高信心閾值便取消所有控制","D":"平均準確率高即可完全自動決策"}'::jsonb, array['L21201']::text[], 2, array['自編', '仿歷屆題型', '錯誤可逆性評估']::text[], null, 158, '自編仿題：L21 AI 導入評估（錯誤可逆性評估）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-06-5', 'L21', 'exam_style', '跨部門專案需明確各階段交付、負責人和驗收者。應先建立什麼？', '{"A":"全交給供應商口頭承諾","B":"只記最終上線日期","C":"工作項目、權責與驗收條件的對照表","D":"只列模型架構"}'::jsonb, array['L21202']::text[], 2, array['自編', '仿歷屆題型', '交付物與驗收責任']::text[], null, 160, '自編仿題：L21 AI 導入規劃（交付物與驗收責任）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-07-1', 'L21', 'exam_style', '客服前端與模型服務由不同團隊開發。為避免整合時欄位與錯誤處理不一致，規劃階段應先定義什麼？', '{"A":"只指定模型的內部層數","B":"把未定義欄位留到正式上線才處理","C":"要求前端猜測模型回傳格式","D":"API 輸入輸出、錯誤格式、版本相容及驗證契約"}'::jsonb, array['L21202']::text[], 2, array['自編', '仿歷屆題型', 'API 契約規格']::text[], null, 162, '自編仿題：L21 AI 導入規劃（API 契約規格）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-07-2', 'L21', 'exam_style', '供應商承諾提供模型服務，企業需約定可用性、回應時間及事故通報責任。應納入哪份約定？', '{"A":"服務水準協議（SLA）","B":"資料標註指南","C":"模型訓練損失函數","D":"使用者介面線框圖"}'::jsonb, array['L21202']::text[], 2, array['自編', '仿歷屆題型', '服務水準協議']::text[], null, 164, '自編仿題：L21 AI 導入規劃（服務水準協議）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-07-3', 'L21', 'exam_style', '專案選擇把敏感資料留在內網，放棄較便宜的公有雲方案。為讓後續維護者了解取捨，應保存什麼？', '{"A":"只保存採購發票","B":"記錄背景、考量方案、決策與後果的架構決策紀錄","C":"只保留最後的部署程式碼","D":"刪除未採用方案的討論"}'::jsonb, array['L21202']::text[], 2, array['自編', '仿歷屆題型', '架構決策紀錄']::text[], null, 166, '自編仿題：L21 AI 導入規劃（架構決策紀錄）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-07-4', 'L21', 'exam_style', '專案中途新增「須支援離線使用」需求，可能改變模型部署架構。規劃者應如何處理？', '{"A":"忽略需求，避免改動時程","B":"先更換模型供應商再討論需求","C":"記錄變更原因、影響、核准決策及對交付與驗收的調整","D":"直接口頭告知工程師並不更新計畫"}'::jsonb, array['L21202']::text[], 2, array['自編', '仿歷屆題型', '需求追溯與變更控制']::text[], null, 168, '自編仿題：L21 AI 導入規劃（需求追溯與變更控制）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-07-5', 'L21', 'exam_style', '採購外部生成式 AI 服務前，服務可能保留提示內容並使用第三方子處理者。風險審查應確認什麼？', '{"A":"只檢查產品介面是否容易操作","B":"只看公開排行榜分數","C":"假設供應商負責所有客戶端法遵","D":"資料用途、保留、存取、子處理者、事故通知及退出條款"}'::jsonb, array['L21203']::text[], 2, array['自編', '仿歷屆題型', '供應商風險審查']::text[], null, 170, '自編仿題：L21 AI 風險管理（供應商風險審查）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-08-1', 'L21', 'exam_style', '高影響 AI 系統的決策被申訴時，團隊需要知道當時使用的模型版本、輸入來源及人工修改。應保留什麼？', '{"A":"依資料最小化與存取控制保存足以重現決策流程的稽核紀錄","B":"只記錄系統是否在線","C":"只保存最新模型，不記歷史版本","D":"將所有個人資料永久複製到公開日誌"}'::jsonb, array['L21203']::text[], 2, array['自編', '仿歷屆題型', '稽核紀錄與責任追溯']::text[], null, 172, '自編仿題：L21 AI 風險管理（稽核紀錄與責任追溯）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-08-2', 'L21', 'exam_style', '模型上線後出現大範圍錯誤推薦，且影響顧客交易。組織應事先建立什麼？', '{"A":"禁止團隊記錄事故以維護聲譽","B":"事故分級、通報窗口、緩解與復原責任及事後檢討流程","C":"等年度稽核時再統計","D":"只要求使用者自行忽略錯誤"}'::jsonb, array['L21203']::text[], 2, array['自編', '仿歷屆題型', '事故通報與回應']::text[], null, 174, '自編仿題：L21 AI 風險管理（事故通報與回應）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-08-3', 'L21', 'exam_style', 'AI 產生 SQL 查詢供資料助理執行。降低模型輸出造成未授權操作風險的控制是？', '{"A":"把資料庫管理員金鑰放入系統提示","B":"只要求模型承諾不輸出危險查詢","C":"使用參數化/允許清單驗證，限制資料庫權限並在執行前檢查","D":"將模型文字直接當 SQL 執行"}'::jsonb, array['L21203']::text[], 2, array['自編', '仿歷屆題型', '生成輸出安全驗證']::text[], null, 176, '自編仿題：L21 AI 風險管理（生成輸出安全驗證）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-08-4', 'L21', 'exam_style', '客戶服務工具會在回覆中使用生成模型，但人工客服仍負責確認高風險內容。對使用者清楚說明系統角色可支持什麼？', '{"A":"證明模型沒有偏差","B":"取代所有品質測試","C":"保證每個回答均正確","D":"適當透明度與知情使用，並避免誤認模型輸出為已核實事實"}'::jsonb, array['L21203']::text[], 2, array['自編', '仿歷屆題型', '模型用途揭露']::text[], null, 178, '自編仿題：L21 AI 風險管理（模型用途揭露）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-08-5', 'L21', 'exam_style', '同一張產品照片經裁切、縮放後分散在訓練與測試集，可能使測試結果偏高。切分前應做什麼？', '{"A":"以適當識別或近重複檢查找出相關影像，再避免跨集合洩漏","B":"只檢查檔名是否完全相同","C":"將測試副本加入訓練以增加樣本","D":"只計算全部資料的平均畫素值"}'::jsonb, array['L21301']::text[], 2, array['自編', '仿歷屆題型', '近重複資料檢查']::text[], null, 180, '自編仿題：L21 數據準備與模型選擇（近重複資料檢查）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-09-1', 'L21', 'exam_style', '建模前需用中位數補缺值。為避免測試資料資訊影響評估，補值器應如何使用？', '{"A":"測試集缺值一律刪除且不記錄","B":"只在訓練集估計中位數，再將同一補值器套用驗證與測試資料","C":"先用全資料計算中位數後切分","D":"每個測試樣本用其標籤決定補值"}'::jsonb, array['L21301']::text[], 2, array['自編', '仿歷屆題型', '訓練集估計缺值補值']::text[], null, 182, '自編仿題：L21 數據準備與模型選擇（訓練集估計缺值補值）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-09-2', 'L21', 'exam_style', '線上資料可能出現訓練時未見的新產品類別。使用類別編碼前應如何規劃？', '{"A":"假設線上永遠不會有新類別","B":"把測試資料中的新類別加進訓練後再報測試分數","C":"定義未知類別的安全處理方式並在訓練、驗證與服務流程一致實作","D":"遇到未知值就任意複製其他類別標籤"}'::jsonb, array['L21301']::text[], 2, array['自編', '仿歷屆題型', '類別未知值處理']::text[], null, 184, '自編仿題：L21 數據準備與模型選擇（類別未知值處理）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-09-3', 'L21', 'exam_style', '團隊依與目標的相關性挑選特徵，並希望報告無偏的測試成績。特徵選擇應在哪裡完成？', '{"A":"先依全資料和測試標籤挑選特徵","B":"看過測試分數後反覆挑特徵直到達標","C":"對訓練與測試分開挑不同特徵後比較","D":"在訓練資料或交叉驗證各訓練折內選擇，再用未觸碰測試集做最後評估"}'::jsonb, array['L21301']::text[], 2, array['自編', '仿歷屆題型', '特徵選擇的驗證邊界']::text[], null, 186, '自編仿題：L21 數據準備與模型選擇（特徵選擇的驗證邊界）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-09-4', 'L21', 'exam_style', '每日匯入資料中，年齡欄位偶爾出現文字「未知」及不合理負數。訓練前的品質檢查應包含什麼？', '{"A":"檢查欄位型別、允許範圍、缺值和異常值並定義處置規則","B":"直接把所有值轉成字串即可","C":"刪掉整個欄位以避免任何錯誤","D":"只看資料列數是否增加"}'::jsonb, array['L21301']::text[], 2, array['自編', '仿歷屆題型', '資料型別與範圍驗證']::text[], null, 188, '自編仿題：L21 數據準備與模型選擇（資料型別與範圍驗證）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-09-5', 'L21', 'exam_style', '調整模型超參數後，團隊希望保留獨立資料估計最終泛化表現。哪種流程較合適？', '{"A":"將驗證和測試資料全部併入每輪訓練","B":"用訓練資料擬合、驗證資料選擇，最後只在未參與調整的測試集評估","C":"每輪調參都依測試集分數選模型","D":"以訓練分數作為最終泛化表現"}'::jsonb, array['L21301']::text[], 2, array['自編', '仿歷屆題型', '驗證集與測試集分工']::text[], null, 190, '自編仿題：L21 數據準備與模型選擇（驗證集與測試集分工）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-10-1', 'L21', 'exam_style', '模型程式更新需先自動檢查相依、資料契約與基本效能門檻，再允許部署。此流程屬於什麼做法？', '{"A":"略過檢查以縮短每次發布時間","B":"只在事故後人工檢查程式碼","C":"在 CI/CD 部署流水線設定自動驗證與品質閘門","D":"直接覆寫正式模型檔"}'::jsonb, array['L21302']::text[], 2, array['自編', '仿歷屆題型', '部署流水線品質閘門']::text[], null, 192, '自編仿題：L21 AI 技術系統集成與部署（部署流水線品質閘門）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-10-2', 'L21', 'exam_style', '負載平衡器需判斷模型服務是否能接收請求。健康檢查最應確認什麼？', '{"A":"只確認機器有電源","B":"每次健康檢查都執行完整大型模型推論且不設逾時","C":"只檢查訓練集準確率","D":"服務程序和必要依賴能否正常回應，並避免只以主機存活代表服務健康"}'::jsonb, array['L21302']::text[], 2, array['自編', '仿歷屆題型', '健康檢查與服務可用性']::text[], null, 194, '自編仿題：L21 AI 技術系統集成與部署（健康檢查與服務可用性）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-10-3', 'L21', 'exam_style', '尖峰時段預測請求可能增加十倍。正式上線前應如何確認系統承載能力？', '{"A":"以接近預期併發和流量型態進行負載測試，觀察延遲、錯誤率與資源使用","B":"只在單一請求下測一次","C":"僅比較模型訓練速度","D":"把尖峰流量忽略並以平均流量估算"}'::jsonb, array['L21302']::text[], 2, array['自編', '仿歷屆題型', '負載與容量測試']::text[], null, 196, '自編仿題：L21 AI 技術系統集成與部署（負載與容量測試）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-10-4', 'L21', 'exam_style', '部署程式需呼叫外部模型服務。為降低金鑰外洩風險，憑證應如何處理？', '{"A":"只要把金鑰字串做 Base64 編碼就算加密","B":"存於受控秘密管理機制，限制權限並定期輪替，避免寫入程式碼或提示","C":"直接寫在前端程式碼供所有人讀取","D":"貼在共享提示模板方便除錯"}'::jsonb, array['L21302']::text[], 2, array['自編', '仿歷屆題型', '機密憑證管理']::text[], null, 198, '自編仿題：L21 AI 技術系統集成與部署（機密憑證管理）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-exam_style-10-5', 'L21', 'exam_style', '線上推論負載日夜差異大，服務須在容量足夠時控制閒置成本。可評估哪項部署能力？', '{"A":"關閉服務監控以減少成本","B":"每次請求都建立永久新伺服器","C":"依負載與資源指標擴縮服務實例，並設定上下限和觀測告警","D":"將模型權重依請求數自動改寫"}'::jsonb, array['L21302']::text[], 2, array['自編', '仿歷屆題型', '自動擴縮與容量界線']::text[], null, 200, '自編仿題：L21 AI 技術系統集成與部署（自動擴縮與容量界線）', 'https://ipd.nat.gov.tw/ipas/certification/AIAP/learning-resources', null, null, null, null, '參照 L21 中級公告試題情境式單選結構；題目和選項為自行撰寫', '[]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-01', 'L21', 'guide_research', '【自然語言處理技術與應用】關於「子詞元切分」，下列哪項敘述正確？', '{"A":"情感分析依預先定義的單位與標籤規範分類情緒或立場，句子級與文件級結果不可混為一談","B":"子詞元方法可將未見詞拆成已知子單位，降低詞彙表外詞問題，但切分會影響詞元序列","C":"詞形還原利用詞彙或語法知識將屈折形式轉為詞元，通常比單純裁字尾更能保留有效詞形","D":"命名實體辨識在文字中找出實體跨度並指派人名、組織、地點等類別"}'::jsonb, array['L21101']::text[], 2, array['自編', '學習指引研究題', '子詞元切分']::text[], null, 101, '自編研究題：依 L21 學習指引 L21101 與第一手技術資料設計（子詞元切分）', 'https://huggingface.co/docs/transformers/tasks/token_classification', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://huggingface.co/docs/transformers/tasks/token_classification","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://huggingface.co/docs/transformers/tasks/masked_language_modeling","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/feature_extraction.html#text-feature-extraction","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://aclanthology.org/P02-1040/","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-02', 'L21', 'guide_research', '【自然語言處理技術與應用】關於「詞形還原」，下列哪項敘述正確？', '{"A":"情感分析依預先定義的單位與標籤規範分類情緒或立場，句子級與文件級結果不可混為一談","B":"BLEU 衡量候選與參考譯文的 n-gram 重疊等訊號，不能單獨保證語意忠實或使用者滿意","C":"詞形還原利用詞彙或語法知識將屈折形式轉為詞元，通常比單純裁字尾更能保留有效詞形","D":"命名實體辨識在文字中找出實體跨度並指派人名、組織、地點等類別"}'::jsonb, array['L21101']::text[], 2, array['自編', '學習指引研究題', '詞形還原']::text[], null, 102, '自編研究題：依 L21 學習指引 L21101 與第一手技術資料設計（詞形還原）', 'https://huggingface.co/docs/transformers/tasks/token_classification', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://huggingface.co/docs/transformers/tasks/token_classification","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://huggingface.co/docs/transformers/tasks/masked_language_modeling","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/feature_extraction.html#text-feature-extraction","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://aclanthology.org/P02-1040/","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-03', 'L21', 'guide_research', '【自然語言處理技術與應用】關於「命名實體跨度」，下列哪項敘述正確？', '{"A":"情感分析依預先定義的單位與標籤規範分類情緒或立場，句子級與文件級結果不可混為一談","B":"BLEU 衡量候選與參考譯文的 n-gram 重疊等訊號，不能單獨保證語意忠實或使用者滿意","C":"子詞元方法可將未見詞拆成已知子單位，降低詞彙表外詞問題，但切分會影響詞元序列","D":"命名實體辨識在文字中找出實體跨度並指派人名、組織、地點等類別"}'::jsonb, array['L21101']::text[], 3, array['自編', '學習指引研究題', '命名實體跨度']::text[], null, 103, '自編研究題：依 L21 學習指引 L21101 與第一手技術資料設計（命名實體跨度）', 'https://huggingface.co/docs/transformers/tasks/token_classification', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://huggingface.co/docs/transformers/tasks/token_classification","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://huggingface.co/docs/transformers/tasks/masked_language_modeling","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/feature_extraction.html#text-feature-extraction","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://aclanthology.org/P02-1040/","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-04', 'L21', 'guide_research', '【自然語言處理技術與應用】關於「文件情感標註」，下列哪項敘述正確？', '{"A":"情感分析依預先定義的單位與標籤規範分類情緒或立場，句子級與文件級結果不可混為一談","B":"BLEU 衡量候選與參考譯文的 n-gram 重疊等訊號，不能單獨保證語意忠實或使用者滿意","C":"子詞元方法可將未見詞拆成已知子單位，降低詞彙表外詞問題，但切分會影響詞元序列","D":"詞形還原利用詞彙或語法知識將屈折形式轉為詞元，通常比單純裁字尾更能保留有效詞形"}'::jsonb, array['L21101']::text[], 2, array['自編', '學習指引研究題', '文件情感標註']::text[], null, 104, '自編研究題：依 L21 學習指引 L21101 與第一手技術資料設計（文件情感標註）', 'https://huggingface.co/docs/transformers/tasks/token_classification', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://huggingface.co/docs/transformers/tasks/token_classification","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://huggingface.co/docs/transformers/tasks/masked_language_modeling","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/feature_extraction.html#text-feature-extraction","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://aclanthology.org/P02-1040/","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-05', 'L21', 'guide_research', '【自然語言處理技術與應用】關於「BLEU 限制」，下列哪項敘述正確？', '{"A":"命名實體辨識在文字中找出實體跨度並指派人名、組織、地點等類別","B":"BLEU 衡量候選與參考譯文的 n-gram 重疊等訊號，不能單獨保證語意忠實或使用者滿意","C":"子詞元方法可將未見詞拆成已知子單位，降低詞彙表外詞問題，但切分會影響詞元序列","D":"詞形還原利用詞彙或語法知識將屈折形式轉為詞元，通常比單純裁字尾更能保留有效詞形"}'::jsonb, array['L21101']::text[], 2, array['自編', '學習指引研究題', 'BLEU 限制']::text[], null, 105, '自編研究題：依 L21 學習指引 L21101 與第一手技術資料設計（BLEU 限制）', 'https://huggingface.co/docs/transformers/tasks/token_classification', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://huggingface.co/docs/transformers/tasks/token_classification","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://huggingface.co/docs/transformers/tasks/masked_language_modeling","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/feature_extraction.html#text-feature-extraction","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://aclanthology.org/P02-1040/","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-06', 'L21', 'guide_research', '【電腦視覺技術與應用】關於「實例分割」，下列哪項敘述正確？', '{"A":"NMS 按信心分數保留候選框並抑制高度重疊的重複預測","B":"精確率關注預測為正的樣本中有多少正確，召回率關注實際正例中找回多少","C":"實例分割提供像素遮罩並區分同類別的不同物件個體","D":"影像分類將整張影像對應到一個或多個類別，不直接提供物件位置"}'::jsonb, array['L21102']::text[], 3, array['自編', '學習指引研究題', '實例分割']::text[], null, 106, '自編研究題：依 L21 學習指引 L21102 與第一手技術資料設計（實例分割）', 'https://pytorch.org/tutorials/beginner/transfer_learning_tutorial.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://pytorch.org/tutorials/beginner/transfer_learning_tutorial.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1506.02640","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-07', 'L21', 'guide_research', '【電腦視覺技術與應用】關於「影像分類」，下列哪項敘述正確？', '{"A":"NMS 按信心分數保留候選框並抑制高度重疊的重複預測","B":"精確率關注預測為正的樣本中有多少正確，召回率關注實際正例中找回多少","C":"遷移學習將預訓練模型所學表示用於相關任務，可凍結部分層或微調參數","D":"影像分類將整張影像對應到一個或多個類別，不直接提供物件位置"}'::jsonb, array['L21102']::text[], 2, array['自編', '學習指引研究題', '影像分類']::text[], null, 107, '自編研究題：依 L21 學習指引 L21102 與第一手技術資料設計（影像分類）', 'https://pytorch.org/tutorials/beginner/transfer_learning_tutorial.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://pytorch.org/tutorials/beginner/transfer_learning_tutorial.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1506.02640","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-08', 'L21', 'guide_research', '【電腦視覺技術與應用】訓練影像模型時，團隊要依訓練集各色彩通道的均值與標準差縮放像素值。這項前處理的目的和做法何者正確？', '{"A":"以訓練集通道均值與標準差正規化，並將相同參數套用於驗證、測試及推論","B":"每張測試影像各自用其標籤計算均值與標準差","C":"把每張影像標籤隨機打亂，以減少通道偏差","D":"依 NMS 閾值刪除重疊邊界框"}'::jsonb, array['L21102']::text[], 2, array['自編', '學習指引研究題', '影像通道正規化']::text[], null, 108, '自編研究題：依 L21 學習指引 L21102 與 PyTorch 影像正規化文件設計', 'https://pytorch.org/vision/stable/generated/torchvision.transforms.Normalize.html', null, null, null, null, null, '[{"title":"torchvision.transforms.Normalize 官方文件","url":"https://pytorch.org/vision/stable/generated/torchvision.transforms.Normalize.html","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-09', 'L21', 'guide_research', '【電腦視覺技術與應用】關於「精確率與召回率」，下列哪項敘述正確？', '{"A":"影像分類將整張影像對應到一個或多個類別，不直接提供物件位置","B":"精確率關注預測為正的樣本中有多少正確，召回率關注實際正例中找回多少","C":"遷移學習將預訓練模型所學表示用於相關任務，可凍結部分層或微調參數","D":"實例分割提供像素遮罩並區分同類別的不同物件個體"}'::jsonb, array['L21102']::text[], 3, array['自編', '學習指引研究題', '精確率與召回率']::text[], null, 109, '自編研究題：依 L21 學習指引 L21102 與第一手技術資料設計（精確率與召回率）', 'https://pytorch.org/tutorials/beginner/transfer_learning_tutorial.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://pytorch.org/tutorials/beginner/transfer_learning_tutorial.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1506.02640","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-10', 'L21', 'guide_research', '【電腦視覺技術與應用】關於「遷移學習」，下列哪項敘述正確？', '{"A":"影像分類將整張影像對應到一個或多個類別，不直接提供物件位置","B":"NMS 按信心分數保留候選框並抑制高度重疊的重複預測","C":"遷移學習將預訓練模型所學表示用於相關任務，可凍結部分層或微調參數","D":"實例分割提供像素遮罩並區分同類別的不同物件個體"}'::jsonb, array['L21102']::text[], 2, array['自編', '學習指引研究題', '遷移學習']::text[], null, 110, '自編研究題：依 L21 學習指引 L21102 與第一手技術資料設計（遷移學習）', 'https://pytorch.org/tutorials/beginner/transfer_learning_tutorial.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://pytorch.org/tutorials/beginner/transfer_learning_tutorial.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1506.02640","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-11', 'L21', 'guide_research', '【生成式 AI 技術與應用】關於「Temperature」，下列哪項敘述正確？', '{"A":"固定且具代表性的評測題集可比較提示或模型版本，但仍須選擇符合任務的品質指標","B":"RAG 在推論時檢索外部資料提供上下文；微調則以訓練更新模型行為或權重","C":"生成式系統應依任務檢查正確性、相關性、安全與可用性，單一流暢度分數不足以代表品質","D":"提高 temperature 通常使取樣分布較平坦、輸出更有變異，不會更新模型權重或保證正確"}'::jsonb, array['L21103']::text[], 2, array['自編', '學習指引研究題', 'Temperature']::text[], null, 111, '自編研究題：依 L21 學習指引 L21103 與第一手技術資料設計（Temperature）', 'https://arxiv.org/abs/1406.2661', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1406.2661","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/2006.11239","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://owasp.org/www-project-top-10-for-large-language-model-applications/","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-12', 'L21', 'guide_research', '【生成式 AI 技術與應用】關於「生成評測集」，下列哪項敘述正確？', '{"A":"固定且具代表性的評測題集可比較提示或模型版本，但仍須選擇符合任務的品質指標","B":"RAG 在推論時檢索外部資料提供上下文；微調則以訓練更新模型行為或權重","C":"生成式系統應依任務檢查正確性、相關性、安全與可用性，單一流暢度分數不足以代表品質","D":"重複懲罰調整已生成詞元分數以減少不必要重複，但不保證內容事實正確"}'::jsonb, array['L21103']::text[], 3, array['自編', '學習指引研究題', '生成評測集']::text[], null, 112, '自編研究題：依 L21 學習指引 L21103 與第一手技術資料設計（生成評測集）', 'https://arxiv.org/abs/1406.2661', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1406.2661","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/2006.11239","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://owasp.org/www-project-top-10-for-large-language-model-applications/","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-13', 'L21', 'guide_research', '【生成式 AI 技術與應用】關於「RAG 與微調」，下列哪項敘述正確？', '{"A":"提高 temperature 通常使取樣分布較平坦、輸出更有變異，不會更新模型權重或保證正確","B":"RAG 在推論時檢索外部資料提供上下文；微調則以訓練更新模型行為或權重","C":"生成式系統應依任務檢查正確性、相關性、安全與可用性，單一流暢度分數不足以代表品質","D":"重複懲罰調整已生成詞元分數以減少不必要重複，但不保證內容事實正確"}'::jsonb, array['L21103']::text[], 2, array['自編', '學習指引研究題', 'RAG 與微調']::text[], null, 113, '自編研究題：依 L21 學習指引 L21103 與第一手技術資料設計（RAG 與微調）', 'https://arxiv.org/abs/1406.2661', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1406.2661","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/2006.11239","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://owasp.org/www-project-top-10-for-large-language-model-applications/","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-14', 'L21', 'guide_research', '【生成式 AI 技術與應用】關於「生成式評估」，下列哪項敘述正確？', '{"A":"提高 temperature 通常使取樣分布較平坦、輸出更有變異，不會更新模型權重或保證正確","B":"固定且具代表性的評測題集可比較提示或模型版本，但仍須選擇符合任務的品質指標","C":"生成式系統應依任務檢查正確性、相關性、安全與可用性，單一流暢度分數不足以代表品質","D":"重複懲罰調整已生成詞元分數以減少不必要重複，但不保證內容事實正確"}'::jsonb, array['L21103']::text[], 2, array['自編', '學習指引研究題', '生成式評估']::text[], null, 114, '自編研究題：依 L21 學習指引 L21103 與第一手技術資料設計（生成式評估）', 'https://arxiv.org/abs/1406.2661', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1406.2661","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/2006.11239","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://owasp.org/www-project-top-10-for-large-language-model-applications/","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-15', 'L21', 'guide_research', '【生成式 AI 技術與應用】關於「重複懲罰」，下列哪項敘述正確？', '{"A":"提高 temperature 通常使取樣分布較平坦、輸出更有變異，不會更新模型權重或保證正確","B":"固定且具代表性的評測題集可比較提示或模型版本，但仍須選擇符合任務的品質指標","C":"RAG 在推論時檢索外部資料提供上下文；微調則以訓練更新模型行為或權重","D":"重複懲罰調整已生成詞元分數以減少不必要重複，但不保證內容事實正確"}'::jsonb, array['L21103']::text[], 3, array['自編', '學習指引研究題', '重複懲罰']::text[], null, 115, '自編研究題：依 L21 學習指引 L21103 與第一手技術資料設計（重複懲罰）', 'https://arxiv.org/abs/1406.2661', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1406.2661","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/2006.11239","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://owasp.org/www-project-top-10-for-large-language-model-applications/","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-16', 'L21', 'guide_research', '【多模態人工智慧應用】關於「CLIP 圖文對比」，下列哪項敘述正確？', '{"A":"CLIP 以配對圖文訓練對比式表示，讓匹配圖文在共同空間可比較並支援零樣本遷移","B":"跨注意力令一模態的查詢參照另一模態的鍵和值，以交換跨模態資訊","C":"文字、影像、音訊等模態通常需適合其資料結構的編碼器，再映射至可融合表示","D":"多模態系統需測試模態缺失情境，並依風險設計遮罩、降級或人工處理"}'::jsonb, array['L21104']::text[], 2, array['自編', '學習指引研究題', 'CLIP 圖文對比']::text[], null, 116, '自編研究題：依 L21 學習指引 L21104 與第一手技術資料設計（CLIP 圖文對比）', 'https://arxiv.org/abs/2103.00020', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/2103.00020","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1706.03762","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1906.00295","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-17', 'L21', 'guide_research', '【多模態人工智慧應用】關於「跨注意力」，下列哪項敘述正確？', '{"A":"頻譜圖顯示頻率成分隨時間的變化，可作為音訊分析的時頻表示","B":"跨注意力令一模態的查詢參照另一模態的鍵和值，以交換跨模態資訊","C":"文字、影像、音訊等模態通常需適合其資料結構的編碼器，再映射至可融合表示","D":"多模態系統需測試模態缺失情境，並依風險設計遮罩、降級或人工處理"}'::jsonb, array['L21104']::text[], 2, array['自編', '學習指引研究題', '跨注意力']::text[], null, 117, '自編研究題：依 L21 學習指引 L21104 與第一手技術資料設計（跨注意力）', 'https://arxiv.org/abs/2103.00020', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/2103.00020","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1706.03762","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1906.00295","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-18', 'L21', 'guide_research', '【多模態人工智慧應用】關於「模態專屬編碼器」，下列哪項敘述正確？', '{"A":"頻譜圖顯示頻率成分隨時間的變化，可作為音訊分析的時頻表示","B":"CLIP 以配對圖文訓練對比式表示，讓匹配圖文在共同空間可比較並支援零樣本遷移","C":"文字、影像、音訊等模態通常需適合其資料結構的編碼器，再映射至可融合表示","D":"多模態系統需測試模態缺失情境，並依風險設計遮罩、降級或人工處理"}'::jsonb, array['L21104']::text[], 3, array['自編', '學習指引研究題', '模態專屬編碼器']::text[], null, 118, '自編研究題：依 L21 學習指引 L21104 與第一手技術資料設計（模態專屬編碼器）', 'https://arxiv.org/abs/2103.00020', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/2103.00020","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1706.03762","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1906.00295","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-19', 'L21', 'guide_research', '【多模態人工智慧應用】關於「多模態缺失」，下列哪項敘述正確？', '{"A":"頻譜圖顯示頻率成分隨時間的變化，可作為音訊分析的時頻表示","B":"CLIP 以配對圖文訓練對比式表示，讓匹配圖文在共同空間可比較並支援零樣本遷移","C":"跨注意力令一模態的查詢參照另一模態的鍵和值，以交換跨模態資訊","D":"多模態系統需測試模態缺失情境，並依風險設計遮罩、降級或人工處理"}'::jsonb, array['L21104']::text[], 2, array['自編', '學習指引研究題', '多模態缺失']::text[], null, 119, '自編研究題：依 L21 學習指引 L21104 與第一手技術資料設計（多模態缺失）', 'https://arxiv.org/abs/2103.00020', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/2103.00020","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1706.03762","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1906.00295","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-20', 'L21', 'guide_research', '【多模態人工智慧應用】關於「音訊頻譜圖」，下列哪項敘述正確？', '{"A":"頻譜圖顯示頻率成分隨時間的變化，可作為音訊分析的時頻表示","B":"CLIP 以配對圖文訓練對比式表示，讓匹配圖文在共同空間可比較並支援零樣本遷移","C":"跨注意力令一模態的查詢參照另一模態的鍵和值，以交換跨模態資訊","D":"文字、影像、音訊等模態通常需適合其資料結構的編碼器，再映射至可融合表示"}'::jsonb, array['L21104']::text[], 2, array['自編', '學習指引研究題', '音訊頻譜圖']::text[], null, 120, '自編研究題：依 L21 學習指引 L21104 與第一手技術資料設計（音訊頻譜圖）', 'https://arxiv.org/abs/2103.00020', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/2103.00020","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1706.03762","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://arxiv.org/abs/1906.00295","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-21', 'L21', 'guide_research', '【AI 導入評估】關於「規則式基線」，下列哪項敘述正確？', '{"A":"敏感度分析觀察成本效益結論如何隨關鍵假設變動，揭露估算不確定性","B":"若任務規則明確穩定，應先比較規則式基線與 AI 在效益、成本、例外及維護上的差異","C":"導入評估應記錄現況基線與可量測目標，避免只用模型離線分數代表業務效益","D":"資料可行性評估需檢查品質、代表性、取得方式、權利與治理條件"}'::jsonb, array['L21201']::text[], 3, array['自編', '學習指引研究題', '規則式基線']::text[], null, 121, '自編研究題：依 L21 學習指引 L21201 與第一手技術資料設計（規則式基線）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-22', 'L21', 'guide_research', '【AI 導入評估】關於「效益基線」，下列哪項敘述正確？', '{"A":"敏感度分析觀察成本效益結論如何隨關鍵假設變動，揭露估算不確定性","B":"AI 導入評估應將自建、採購、流程改善或維持現況等可行替代方案依需求比較","C":"導入評估應記錄現況基線與可量測目標，避免只用模型離線分數代表業務效益","D":"資料可行性評估需檢查品質、代表性、取得方式、權利與治理條件"}'::jsonb, array['L21201']::text[], 2, array['自編', '學習指引研究題', '效益基線']::text[], null, 122, '自編研究題：依 L21 學習指引 L21201 與第一手技術資料設計（效益基線）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
