  ('l21-guide_research-25', 'L21', 'guide_research', '【AI 導入評估】關於「替代方案比較」，下列哪項敘述正確？', '{"A":"資料可行性評估需檢查品質、代表性、取得方式、權利與治理條件","B":"AI 導入評估應將自建、採購、流程改善或維持現況等可行替代方案依需求比較","C":"若任務規則明確穩定，應先比較規則式基線與 AI 在效益、成本、例外及維護上的差異","D":"導入評估應記錄現況基線與可量測目標，避免只用模型離線分數代表業務效益"}'::jsonb, array['L21201']::text[], 2, array['自編', '學習指引研究題', '替代方案比較']::text[], null, 125, '自編研究題：依 L21 學習指引 L21201 與第一手技術資料設計（替代方案比較）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-26', 'L21', 'guide_research', '【AI 導入規劃】關於「分階段路線圖」，下列哪項敘述正確？', '{"A":"RACI 區分執行、負責、諮詢與知會角色，讓跨部門工作和決策權可追蹤","B":"AI 流程需定義模型輸出如何進入工作、例外如何處理及何時轉人工","C":"分階段導入先驗證有限範圍，再依證據、風險和門檻決定擴大或停止","D":"試點資料與場域應涵蓋重要部署情境，否則試點結果不能直接外推到未測族群"}'::jsonb, array['L21202']::text[], 2, array['自編', '學習指引研究題', '分階段路線圖']::text[], null, 126, '自編研究題：依 L21 學習指引 L21202 與第一手技術資料設計（分階段路線圖）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-27', 'L21', 'guide_research', '【AI 導入規劃】關於「試點代表性」，下列哪項敘述正確？', '{"A":"RACI 區分執行、負責、諮詢與知會角色，讓跨部門工作和決策權可追蹤","B":"AI 流程需定義模型輸出如何進入工作、例外如何處理及何時轉人工","C":"使用者訓練、溝通、回饋和工作流程配套影響系統採用，不能只看模型效能","D":"試點資料與場域應涵蓋重要部署情境，否則試點結果不能直接外推到未測族群"}'::jsonb, array['L21202']::text[], 3, array['自編', '學習指引研究題', '試點代表性']::text[], null, 127, '自編研究題：依 L21 學習指引 L21202 與第一手技術資料設計（試點代表性）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-28', 'L21', 'guide_research', '【AI 導入規劃】關於「RACI 權責」，下列哪項敘述正確？', '{"A":"RACI 區分執行、負責、諮詢與知會角色，讓跨部門工作和決策權可追蹤","B":"AI 流程需定義模型輸出如何進入工作、例外如何處理及何時轉人工","C":"使用者訓練、溝通、回饋和工作流程配套影響系統採用，不能只看模型效能","D":"分階段導入先驗證有限範圍，再依證據、風險和門檻決定擴大或停止"}'::jsonb, array['L21202']::text[], 2, array['自編', '學習指引研究題', 'RACI 權責']::text[], null, 128, '自編研究題：依 L21 學習指引 L21202 與第一手技術資料設計（RACI 權責）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-29', 'L21', 'guide_research', '【AI 導入規劃】關於「流程交接設計」，下列哪項敘述正確？', '{"A":"試點資料與場域應涵蓋重要部署情境，否則試點結果不能直接外推到未測族群","B":"AI 流程需定義模型輸出如何進入工作、例外如何處理及何時轉人工","C":"使用者訓練、溝通、回饋和工作流程配套影響系統採用，不能只看模型效能","D":"分階段導入先驗證有限範圍，再依證據、風險和門檻決定擴大或停止"}'::jsonb, array['L21202']::text[], 2, array['自編', '學習指引研究題', '流程交接設計']::text[], null, 129, '自編研究題：依 L21 學習指引 L21202 與第一手技術資料設計（流程交接設計）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-30', 'L21', 'guide_research', '【AI 導入規劃】關於「使用者採納」，下列哪項敘述正確？', '{"A":"試點資料與場域應涵蓋重要部署情境，否則試點結果不能直接外推到未測族群","B":"RACI 區分執行、負責、諮詢與知會角色，讓跨部門工作和決策權可追蹤","C":"使用者訓練、溝通、回饋和工作流程配套影響系統採用，不能只看模型效能","D":"分階段導入先驗證有限範圍，再依證據、風險和門檻決定擴大或停止"}'::jsonb, array['L21202']::text[], 3, array['自編', '學習指引研究題', '使用者採納']::text[], null, 130, '自編研究題：依 L21 學習指引 L21202 與第一手技術資料設計（使用者採納）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-31', 'L21', 'guide_research', '【AI 風險管理】關於「NIST AI RMF 四功能」，下列哪項敘述正確？', '{"A":"威脅建模辨識資產、信任邊界、資料流、可執行工具及可能濫用方式","B":"假名化替換直接識別符可降低暴露，但若可連結額外資訊仍有再識別風險","C":"公平性檢查需依情境比較相關群體的錯誤或影響，整體平均可能掩蓋子群差異","D":"NIST AI RMF 的 Govern、Map、Measure、Manage 分別涵蓋治理、情境辨識、風險衡量與風險處置"}'::jsonb, array['L21203']::text[], 2, array['自編', '學習指引研究題', 'NIST AI RMF 四功能']::text[], null, 131, '自編研究題：依 L21 學習指引 L21203 與第一手技術資料設計（NIST AI RMF 四功能）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://www.nist.gov/privacy-framework","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-32', 'L21', 'guide_research', '【AI 風險管理】關於「威脅建模」，下列哪項敘述正確？', '{"A":"威脅建模辨識資產、信任邊界、資料流、可執行工具及可能濫用方式","B":"假名化替換直接識別符可降低暴露，但若可連結額外資訊仍有再識別風險","C":"公平性檢查需依情境比較相關群體的錯誤或影響，整體平均可能掩蓋子群差異","D":"有效監督要求人員有足夠資訊、能力、時間與介入權，不能只在流程中名義上放一位覆核者"}'::jsonb, array['L21203']::text[], 2, array['自編', '學習指引研究題', '威脅建模']::text[], null, 132, '自編研究題：依 L21 學習指引 L21203 與第一手技術資料設計（威脅建模）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://www.nist.gov/privacy-framework","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
