  ('l21-guide_research-34', 'L21', 'guide_research', '【AI 風險管理】關於「群體公平評估」，下列哪項敘述正確？', '{"A":"NIST AI RMF 的 Govern、Map、Measure、Manage 分別涵蓋治理、情境辨識、風險衡量與風險處置","B":"威脅建模辨識資產、信任邊界、資料流、可執行工具及可能濫用方式","C":"公平性檢查需依情境比較相關群體的錯誤或影響，整體平均可能掩蓋子群差異","D":"有效監督要求人員有足夠資訊、能力、時間與介入權，不能只在流程中名義上放一位覆核者"}'::jsonb, array['L21203']::text[], 2, array['自編', '學習指引研究題', '群體公平評估']::text[], null, 134, '自編研究題：依 L21 學習指引 L21203 與第一手技術資料設計（群體公平評估）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://www.nist.gov/privacy-framework","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-35', 'L21', 'guide_research', '【AI 風險管理】關於「有效人類監督」，下列哪項敘述正確？', '{"A":"NIST AI RMF 的 Govern、Map、Measure、Manage 分別涵蓋治理、情境辨識、風險衡量與風險處置","B":"威脅建模辨識資產、信任邊界、資料流、可執行工具及可能濫用方式","C":"假名化替換直接識別符可降低暴露，但若可連結額外資訊仍有再識別風險","D":"有效監督要求人員有足夠資訊、能力、時間與介入權，不能只在流程中名義上放一位覆核者"}'::jsonb, array['L21203']::text[], 2, array['自編', '學習指引研究題', '有效人類監督']::text[], null, 135, '自編研究題：依 L21 學習指引 L21203 與第一手技術資料設計（有效人類監督）', 'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://www.nist.gov/privacy-framework","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-36', 'L21', 'guide_research', '【數據準備與模型選擇】關於「標註仲裁」，下列哪項敘述正確？', '{"A":"標註分歧應依清楚規範討論仲裁並記錄，不宜不加分析地把矛盾標籤交給模型","B":"訓練資料應涵蓋預期部署族群、設備與情境；樣本總量大不等於代表性足夠","C":"預測未來時應依時間先後切分資料，避免未來資訊進入訓練再評估過去","D":"同一病患、客戶或來源的相關記錄宜依群組切分，避免相似個體跨訓練與測試造成洩漏"}'::jsonb, array['L21301']::text[], 3, array['自編', '學習指引研究題', '標註仲裁']::text[], null, 136, '自編研究題：依 L21 學習指引 L21301 與第一手技術資料設計（標註仲裁）', 'https://scikit-learn.org/stable/common_pitfalls.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/common_pitfalls.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/cross_validation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-37', 'L21', 'guide_research', '【數據準備與模型選擇】關於「資料代表性」，下列哪項敘述正確？', '{"A":"同一特徵應有一致定義與單位，否則相同數值可能代表不同量綱","B":"訓練資料應涵蓋預期部署族群、設備與情境；樣本總量大不等於代表性足夠","C":"預測未來時應依時間先後切分資料，避免未來資訊進入訓練再評估過去","D":"同一病患、客戶或來源的相關記錄宜依群組切分，避免相似個體跨訓練與測試造成洩漏"}'::jsonb, array['L21301']::text[], 2, array['自編', '學習指引研究題', '資料代表性']::text[], null, 137, '自編研究題：依 L21 學習指引 L21301 與第一手技術資料設計（資料代表性）', 'https://scikit-learn.org/stable/common_pitfalls.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/common_pitfalls.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/cross_validation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-38', 'L21', 'guide_research', '【數據準備與模型選擇】關於「時間切分」，下列哪項敘述正確？', '{"A":"同一特徵應有一致定義與單位，否則相同數值可能代表不同量綱","B":"類別不平衡時應檢查少數類 precision、recall 或 PR 曲線，不能只依賴 accuracy","C":"預測未來時應依時間先後切分資料，避免未來資訊進入訓練再評估過去","D":"同一病患、客戶或來源的相關記錄宜依群組切分，避免相似個體跨訓練與測試造成洩漏"}'::jsonb, array['L21301']::text[], 2, array['自編', '學習指引研究題', '時間切分']::text[], null, 138, '自編研究題：依 L21 學習指引 L21301 與第一手技術資料設計（時間切分）', 'https://scikit-learn.org/stable/common_pitfalls.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/common_pitfalls.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/cross_validation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-39', 'L21', 'guide_research', '【數據準備與模型選擇】關於「群組切分」，下列哪項敘述正確？', '{"A":"同一特徵應有一致定義與單位，否則相同數值可能代表不同量綱","B":"類別不平衡時應檢查少數類 precision、recall 或 PR 曲線，不能只依賴 accuracy","C":"資料血緣保留來源、轉換、標註與版本關係，支援重現、品質排查和權利追溯","D":"同一病患、客戶或來源的相關記錄宜依群組切分，避免相似個體跨訓練與測試造成洩漏"}'::jsonb, array['L21301']::text[], 3, array['自編', '學習指引研究題', '群組切分']::text[], null, 139, '自編研究題：依 L21 學習指引 L21301 與第一手技術資料設計（群組切分）', 'https://scikit-learn.org/stable/common_pitfalls.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/common_pitfalls.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/cross_validation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-40', 'L21', 'guide_research', '【數據準備與模型選擇】關於「特徵單位一致」，下列哪項敘述正確？', '{"A":"同一特徵應有一致定義與單位，否則相同數值可能代表不同量綱","B":"類別不平衡時應檢查少數類 precision、recall 或 PR 曲線，不能只依賴 accuracy","C":"資料血緣保留來源、轉換、標註與版本關係，支援重現、品質排查和權利追溯","D":"標註分歧應依清楚規範討論仲裁並記錄，不宜不加分析地把矛盾標籤交給模型"}'::jsonb, array['L21301']::text[], 2, array['自編', '學習指引研究題', '特徵單位一致']::text[], null, 140, '自編研究題：依 L21 學習指引 L21301 與第一手技術資料設計（特徵單位一致）', 'https://scikit-learn.org/stable/common_pitfalls.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/common_pitfalls.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/cross_validation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-41', 'L21', 'guide_research', '【數據準備與模型選擇】關於「PR 指標」，下列哪項敘述正確？', '{"A":"訓練資料應涵蓋預期部署族群、設備與情境；樣本總量大不等於代表性足夠","B":"類別不平衡時應檢查少數類 precision、recall 或 PR 曲線，不能只依賴 accuracy","C":"資料血緣保留來源、轉換、標註與版本關係，支援重現、品質排查和權利追溯","D":"標註分歧應依清楚規範討論仲裁並記錄，不宜不加分析地把矛盾標籤交給模型"}'::jsonb, array['L21301']::text[], 2, array['自編', '學習指引研究題', 'PR 指標']::text[], null, 141, '自編研究題：依 L21 學習指引 L21301 與第一手技術資料設計（PR 指標）', 'https://scikit-learn.org/stable/common_pitfalls.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/common_pitfalls.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/cross_validation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-42', 'L21', 'guide_research', '【數據準備與模型選擇】關於「資料血緣」，下列哪項敘述正確？', '{"A":"訓練資料應涵蓋預期部署族群、設備與情境；樣本總量大不等於代表性足夠","B":"預測未來時應依時間先後切分資料，避免未來資訊進入訓練再評估過去","C":"資料血緣保留來源、轉換、標註與版本關係，支援重現、品質排查和權利追溯","D":"標註分歧應依清楚規範討論仲裁並記錄，不宜不加分析地把矛盾標籤交給模型"}'::jsonb, array['L21301']::text[], 3, array['自編', '學習指引研究題', '資料血緣']::text[], null, 142, '自編研究題：依 L21 學習指引 L21301 與第一手技術資料設計（資料血緣）', 'https://scikit-learn.org/stable/common_pitfalls.html', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/common_pitfalls.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/cross_validation.html","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://scikit-learn.org/stable/modules/model_evaluation.html","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-43', 'L21', 'guide_research', '【AI 技術系統集成與部署】關於「批次推論」，下列哪項敘述正確？', '{"A":"線上推論在請求發生時回應，設計需驗證端到端延遲與併發容量","B":"SLO 以可量測門檻描述服務品質，例如可用性或延遲百分位","C":"金絲雀部署先將少量流量導向新版並觀察指標，再決定擴大或回退","D":"批次推論適合可排程且能容忍延遲的大量資料處理"}'::jsonb, array['L21302']::text[], 2, array['自編', '學習指引研究題', '批次推論']::text[], null, 143, '自編研究題：依 L21 學習指引 L21302 與第一手技術資料設計（批次推論）', 'https://mlflow.org/docs/latest/ml/model-registry/workflow/', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/deployment/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-44', 'L21', 'guide_research', '【AI 技術系統集成與部署】關於「線上推論」，下列哪項敘述正確？', '{"A":"線上推論在請求發生時回應，設計需驗證端到端延遲與併發容量","B":"SLO 以可量測門檻描述服務品質，例如可用性或延遲百分位","C":"金絲雀部署先將少量流量導向新版並觀察指標，再決定擴大或回退","D":"影子部署讓新版平行接收流量並記錄結果，但不直接影響使用者決策"}'::jsonb, array['L21302']::text[], 2, array['自編', '學習指引研究題', '線上推論']::text[], null, 144, '自編研究題：依 L21 學習指引 L21302 與第一手技術資料設計（線上推論）', 'https://mlflow.org/docs/latest/ml/model-registry/workflow/', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/deployment/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-45', 'L21', 'guide_research', '【AI 技術系統集成與部署】關於「服務水準目標」，下列哪項敘述正確？', '{"A":"模型登錄庫管理模型版本與中繼資料，支援審查、升版和部署追蹤","B":"SLO 以可量測門檻描述服務品質，例如可用性或延遲百分位","C":"金絲雀部署先將少量流量導向新版並觀察指標，再決定擴大或回退","D":"影子部署讓新版平行接收流量並記錄結果，但不直接影響使用者決策"}'::jsonb, array['L21302']::text[], 3, array['自編', '學習指引研究題', '服務水準目標']::text[], null, 145, '自編研究題：依 L21 學習指引 L21302 與第一手技術資料設計（服務水準目標）', 'https://mlflow.org/docs/latest/ml/model-registry/workflow/', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/deployment/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-46', 'L21', 'guide_research', '【AI 技術系統集成與部署】關於「金絲雀部署」，下列哪項敘述正確？', '{"A":"模型登錄庫管理模型版本與中繼資料，支援審查、升版和部署追蹤","B":"容器將應用程式及相依環境封裝，提升部署環境一致性但不自動保證安全","C":"金絲雀部署先將少量流量導向新版並觀察指標，再決定擴大或回退","D":"影子部署讓新版平行接收流量並記錄結果，但不直接影響使用者決策"}'::jsonb, array['L21302']::text[], 2, array['自編', '學習指引研究題', '金絲雀部署']::text[], null, 146, '自編研究題：依 L21 學習指引 L21302 與第一手技術資料設計（金絲雀部署）', 'https://mlflow.org/docs/latest/ml/model-registry/workflow/', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/deployment/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-47', 'L21', 'guide_research', '【AI 技術系統集成與部署】關於「影子部署」，下列哪項敘述正確？', '{"A":"模型登錄庫管理模型版本與中繼資料，支援審查、升版和部署追蹤","B":"容器將應用程式及相依環境封裝，提升部署環境一致性但不自動保證安全","C":"模型逾時或輸入異常時應有安全替代流程、告警與紀錄，避免無限重試或任意輸出","D":"影子部署讓新版平行接收流量並記錄結果，但不直接影響使用者決策"}'::jsonb, array['L21302']::text[], 2, array['自編', '學習指引研究題', '影子部署']::text[], null, 147, '自編研究題：依 L21 學習指引 L21302 與第一手技術資料設計（影子部署）', 'https://mlflow.org/docs/latest/ml/model-registry/workflow/', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/deployment/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-48', 'L21', 'guide_research', '【AI 技術系統集成與部署】關於「模型登錄庫」，下列哪項敘述正確？', '{"A":"模型登錄庫管理模型版本與中繼資料，支援審查、升版和部署追蹤","B":"容器將應用程式及相依環境封裝，提升部署環境一致性但不自動保證安全","C":"模型逾時或輸入異常時應有安全替代流程、告警與紀錄，避免無限重試或任意輸出","D":"批次推論適合可排程且能容忍延遲的大量資料處理"}'::jsonb, array['L21302']::text[], 3, array['自編', '學習指引研究題', '模型登錄庫']::text[], null, 148, '自編研究題：依 L21 學習指引 L21302 與第一手技術資料設計（模型登錄庫）', 'https://mlflow.org/docs/latest/ml/model-registry/workflow/', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/deployment/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-49', 'L21', 'guide_research', '【AI 技術系統集成與部署】關於「容器封裝」，下列哪項敘述正確？', '{"A":"線上推論在請求發生時回應，設計需驗證端到端延遲與併發容量","B":"容器將應用程式及相依環境封裝，提升部署環境一致性但不自動保證安全","C":"模型逾時或輸入異常時應有安全替代流程、告警與紀錄，避免無限重試或任意輸出","D":"批次推論適合可排程且能容忍延遲的大量資料處理"}'::jsonb, array['L21302']::text[], 2, array['自編', '學習指引研究題', '容器封裝']::text[], null, 149, '自編研究題：依 L21 學習指引 L21302 與第一手技術資料設計（容器封裝）', 'https://mlflow.org/docs/latest/ml/model-registry/workflow/', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/deployment/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('l21-guide_research-50', 'L21', 'guide_research', '【AI 技術系統集成與部署】關於「安全 fallback」，下列哪項敘述正確？', '{"A":"線上推論在請求發生時回應，設計需驗證端到端延遲與併發容量","B":"SLO 以可量測門檻描述服務品質，例如可用性或延遲百分位","C":"模型逾時或輸入異常時應有安全替代流程、告警與紀錄，避免無限重試或任意輸出","D":"批次推論適合可排程且能容忍延遲的大量資料處理"}'::jsonb, array['L21302']::text[], 2, array['自編', '學習指引研究題', '安全 fallback']::text[], null, 150, '自編研究題：依 L21 學習指引 L21302 與第一手技術資料設計（安全 fallback）', 'https://mlflow.org/docs/latest/ml/model-registry/workflow/', null, null, null, null, null, '[{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://mlflow.org/docs/latest/ml/deployment/","published":"查證日期 2026-09-29"},{"title":"第一手技術文件或原始資料","url":"https://cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning","published":"查證日期 2026-09-29"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q01', 'L23', 'official', '某零售企業建立一個銷售預測模型,希望評估該模型在不同月份的新資料 上,是否仍能維持穩定的預測表現。資料科學團隊計畫利用統計方法檢驗 模型對未觀察資料的適應能力與泛化效果。下列哪一種方法最適合用於此 目的?', '{"A":"F 檢定(F-test);","B":"交叉驗證(Cross-Validation);","C":"配對樣本 t 檢定(Paired-sample t-test);","D":"卡方檢定(Chi-square Test)"}'::jsonb, array['L23-5.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 1, '114 年第 2 次中級第三科公告試題，第 1 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 1, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q02', 'L23', 'official', '在建立迴歸或分類模型時,若希望避免模型過度擬合(Overfitting) ,可 透過加入正則化項以限制模型的複雜度。其中,L1 正則化(Lasso)的主 要效果為何?', '{"A":"增加模型參數的數量,以提升表現靈活度;","B":"強化梯度穩定性,避免參數更新過度震盪;","C":"產生稀疏模型(Sparse Model) ,使部分參數權重收斂為零;","D":"提高學習率(Learning Rate) ,加速模型收斂速度"}'::jsonb, array['L23-5.4']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 2, '114 年第 2 次中級第三科公告試題，第 2 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 2, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q03', 'L23', 'official', '在訓練非線性模型時,若目標函數為非凸函數(Non-convex Function), 演算法在參數更新過程中可能出現多個極值點,導致最佳化結果不穩定。 請問此時最可能發生下列哪一種情況?', '{"A":"梯度消失;","B":"資料過少;","C":"局部最優解;","D":"過擬合"}'::jsonb, array['L23-3.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 3, '114 年第 2 次中級第三科公告試題，第 3 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 3, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q04', 'L23', 'official', '在執行 DBSCAN(Density-Based Spatial Clustering of Applications with Noise)群集分析時,若某資料點鄰域內的樣本數不足以形成核心點 (Core Point) ,且該點未被任何核心點的鄰域所包含,也未與其他群集形 成密度可達關係(Density Reachability) ,此資料點最終將被歸類為哪一 種類型?', '{"A":"鄰近點(Neighbor Point);","B":"雜訊點(Noise Point);","C":"邊界點(Border Point);","D":"潛在點(Potential Point)"}'::jsonb, array['L23-4.2']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 4, '114 年第 2 次中級第三科公告試題，第 4 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 4, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q05', 'L23', 'official', '某智慧製造公司開發一套影像辨識系統,用於自動檢測生產線上的瑕疵產 品。系統採用卷積神經網路(Convolutional Neural Network, CNN)作為 主要模型架構,其中第一層卷積層(Convolutional Layer)主要負責的功 能為下列何者?', '{"A":"自動提取輸入影像中的局部特徵;","B":"降低影像維度以加速運算效率;","C":"增加神經元與參數數量以提升模型容量;","D":"整合所有特徵並輸出最終分類結果"}'::jsonb, array['L23-4.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 5, '114 年第 2 次中級第三科公告試題，第 5 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 5, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q06', 'L23', 'official', '某智慧城市團隊開發一套交通監控系統,用於即時辨識路口監視器影像中 的車輛與行人。團隊比較後發現,卷積神經網路(Convolutional Neural Network, CNN)在訓練與推論效率上,明顯優於傳統的全連接神經網路 (Fully Connected Neural Network, FCNN) 。請問下列何者為主要原因?', '{"A":"CNN 能自動學習影像的旋轉與比例不變性;","B":"CNN 可直接跳過人工特徵提取步驟進行分類;","C":"CNN 透過區域感知(Local Receptive Field)與參數共享(Parameter Sharing)機制,降低模型參數量與運算複雜度;","D":"CNN 捨棄激勵函數(Activation Function) ,以加快運算速度"}'::jsonb, array['L23-4.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 6, '114 年第 2 次中級第三科公告試題，第 6 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 6, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q07', 'L23', 'official', '下列哪一種應用最適合採用長短期記憶網路(Long Short-Term Memory, LSTM)模型?', '{"A":"預測未來七天的電力需求變化趨勢;","B":"辨識監視影像中不同類別的物件;","C":"將大量顧客資料依相似特徵自動分群;","D":"將高維度的感測器資料壓縮成低維表示"}'::jsonb, array['L23-4.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 7, '114 年第 2 次中級第三科公告試題，第 7 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 7, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q08', 'L23', 'official', '資訊增益(Information Gain)常用於衡量特徵對分類結果的不確定性貢 獻程度,並據以進行特徵選擇。此方法主要應用於下列哪一類模型架構 中?', '{"A":"使用 L1 正則化進行特徵篩選的線性模型;","B":"利用激活函數(Activation Function)進行特徵擷取的深度神經網 路;","C":"透過核函數(Kernel Function)將特徵映射至高維空間的分類模型;","D":"透過遞迴分裂方式建立分類規則的決策樹模型"}'::jsonb, array['L23-5.4']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 8, '114 年第 2 次中級第三科公告試題，第 8 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 8, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q09', 'L23', 'official', '在建構以距離為基礎的機器學習模型(如 KNN、SVM)時,下列哪一項資料 前處理方式最為關鍵?', '{"A":"進行特徵縮放(Feature Scaling) ,使各特徵變數具有相似的數值範 圍;","B":"將連續型特徵變數轉換為類別型變數;","C":"以平均值或中位數進行缺失值補齊;","D":"進行隨機抽樣以平衡資料筆數"}'::jsonb, array['L23-5.1']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 9, '114 年第 2 次中級第三科公告試題，第 9 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 9, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q10', 'L23', 'official', '下列哪一種應用情境最適合導入 AutoML,以提升模型開發效率?', '{"A":"公司已有完整的 MLOps 平台與資深資料科學團隊,模型更新採固定流 程;","B":"製造部門的生產良率模型已長期穩定運作,只需定期調整參數;","C":"行銷部門希望在短時間內比較多種顧客流失預測模型,缺乏專職工程師 與時間進行手動建模;","D":"財務部門正在開發高度客製化的信用風險評估模型,需要精細控制特徵 工程與演算法細節"}'::jsonb, array['L23-5.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 10, '114 年第 2 次中級第三科公告試題，第 10 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 10, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q11', 'L23', 'official', '相較於 Grid Search,Random Search 在超參數調整上具備哪一項主要優 勢?', '{"A":"可自動產生模型架構;","B":"可使用更大的訓練集;","C":"避免模型過擬合;","D":"能更有效率搜尋高維參數空間"}'::jsonb, array['L23-5.4']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 11, '114 年第 2 次中級第三科公告試題，第 11 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 11, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q12', 'L23', 'official', '某智慧製造公司開發一套設備故障預測系統,利用感測器資料訓練深度神 經網路(Deep Neural Network, DNN)模型,以提前偵測異常運作跡象。 在訓練過程中,團隊發現模型收斂速度不穩定:有時過快導致過擬合,有 時又遲遲無法達到最佳準確率。開發團隊可以藉由調整下列哪一項超參數 (Hyperparameter)以改善此問題?', '{"A":"每個神經元的輸出結果;","B":"損失函數(Loss Function)在訓練過程中的梯度變化值(Gradient);","C":"學習率(Learning Rate) ,控制模型權重更新的速度;","D":"模型在訓練後產生的權重值"}'::jsonb, array['L23-5.4']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 12, '114 年第 2 次中級第三科公告試題，第 12 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 12, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
