  ('L23-114-S2-Q14', 'L23', 'official', '下列哪一種 AI 應用情境中,模型的可解釋性(Explainability)最為關 鍵?', '{"A":"電商平台利用深度學習模型預測用戶的下一次購買時間,以優化推播行 銷策略;","B":"新創公司使用機器學習演算法自動調整廣告出價策略,以提升點擊轉換","C":"醫院導入 AI 模型分析病患影像並給出腫瘤惡性可能性,作為臨床醫師 診斷依據;","D":"銀行導入 AI 模型預測客戶流失率,並自動推薦留客優惠方案"}'::jsonb, array['L23-3.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 14, '114 年第 2 次中級第三科公告試題，第 14 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 14, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
