  ('L23-114-S2-Q18', 'L23', 'official', '下列何者最能同時反映 XGBoost(eXtreme Gradient Boosting)相較於傳 統梯度提升決策樹(Gradient Boosting Decision Tree, GBDT)的主要技 術改進?', '{"A":"引入正則化項(Regularization)以抑制過擬合,並支援缺失值自動處 理與並行化訓練;","B":"改以隨機森林(Random Forest)架構取代樹模型以提升準確率;","C":"以類神經網路(Neural Network)取代弱分類器(Weak Learners);","D":"採用批次正規化(Batch Normalization)技術提升模型穩定性"}'::jsonb, array['L23-5.4']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 18, '114 年第 2 次中級第三科公告試題，第 18 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 18, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q19', 'L23', 'official', '某醫療機構開發疾病早期偵測模型,正樣本(確診病例)僅佔 3%。在模型 訓練與評估過程中,下列哪一種作法最不適合用於提升對少數類病例的預 測能力?', '{"A":"使用 SMOTE 過採樣;","B":"調整類別權重;","C":"使用準確率(Accuracy)作為評估指標;","D":"欠採樣多數類(Undersampling the majority class)"}'::jsonb, array['L23-5.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 19, '114 年第 2 次中級第三科公告試題，第 19 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 19, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q20', 'L23', 'official', '某電子商務公司為開發商品評論情感分析模型,希望模型能捕捉評論中不 同特徵之間的關聯影響,例如「商品價格」與「顧客滿意度」的互動效 果。下列哪一種特徵工程設計方式最適合用於建立互動特徵(Interaction Features)?', '{"A":"將單一特徵取平方;","B":"對所有特徵進行對數轉換;","C":"將兩個或多個特徵進行乘積或交互組合;","D":"對特徵進行標準化"}'::jsonb, array['L23-5.1']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 20, '114 年第 2 次中級第三科公告試題，第 20 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 20, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q21', 'L23', 'official', '某語音辨識系統開發團隊採用 Transformer 架構,為了讓模型能同時理解 語音片段中的發音特徵、語速變化與語意脈絡等多層次資訊,團隊在設計 中導入了多頭注意力(Multi-head Attention)機制。請問下列何者為此 機制的主要優點?', '{"A":"減少模型參數量以降低訓練成本;","B":"加速整體注意力計算過程;","C":"從不同表示子空間(Representation Subspaces)同時捕捉多樣化關聯 資訊;","D":"避免梯度消失(Gradient Vanishing)問題"}'::jsonb, array['L23-4.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 21, '114 年第 2 次中級第三科公告試題，第 21 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 21, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q22', 'L23', 'official', '某電商平台希望預測顧客是否會購買特定商品。系統蒐集顧客的瀏覽紀 錄、停留時間、商品類別偏好與過去購買行為,並以此推估「在觀察到這 些行為特徵的情況下,該顧客會購買的機率」 。若模型採用貝氏定理 (Bayes’Theorem)進行推論,下列敘述何者最符合其核心運作機制?', '{"A":"根據歷史樣本自動分群,找出行為相似的顧客群;","B":"以條件機率方式計算顧客屬於「會購買」或「不會購買」的分類機率;","C":"以最小平方誤差(Mean Squared Error)為損失函數,預測顧客的購買 金額;","D":"依據回饋信號(Feedback Signal)透過強化學習(Reinforcement Learning)動態調整推薦策略"}'::jsonb, array['L23-4.2']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 22, '114 年第 2 次中級第三科公告試題，第 22 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 22, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q23', 'L23', 'official', '一家再生能源公司希望預測未來三個月太陽能發電量的波動範圍。由於氣 候條件具有高度隨機性,且輸入變數(如日照時數、雲量、溫度)之間存 在不確定關係,工程團隊決定以隨機抽樣方式模擬多種可能情境,以估算 整體發電量的機率分佈與風險區間。請問此時所採用的技術最符合下列哪 一種方法?', '{"A":"蒙地卡羅方法(Monte Carlo Method);","B":"K-means 聚類(K-means Clustering);","C":"支持向量迴歸(Support Vector Regression, SVR);","D":"特徵選取(Feature Selection)"}'::jsonb, array['L23-4.2']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 23, '114 年第 2 次中級第三科公告試題，第 23 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 23, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q24', 'L23', 'official', '某房地產公司利用多元迴歸模型(Multiple Regression Model)預測房 價,並繪製殘差圖(Residual Plot)檢查模型品質。結果顯示部分資料點 的殘差極大,且在高價區樣本中出現系統性彎曲分佈現象。根據此觀察, 下列何者為最可能的正確解釋?', '{"A":"模型過度擬合(Overfitting) ,導致在訓練資料上表現過好、泛化能力 不足;","B":"模型特徵數量不足,導致欠擬合(Underfitting);","C":"模型存在異常值(Outlier)或非線性關係,違反迴歸假設;","D":"殘差圖呈現隨機分佈,表示模型已完全符合所有假設"}'::jsonb, array['L23-4.1']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 24, '114 年第 2 次中級第三科公告試題，第 24 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 24, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q25', 'L23', 'official', '某金融機構正在建立傳統信用評分卡模型,採用邏輯迴歸(Logistic Regression)作為建模方法,並依循監理機關建議的標準化流程進行模型 開發。下列哪一項不是傳統信用評分卡模型開發流程中的常見步驟?', '{"A":"使用生成式模型進行特徵學習;","B":"進行特徵選擇與多重共線性(Multicollinearity)分析;","C":"進行分箱(Binning)與資訊值(Information Value, IV)檢定;","D":"使用樣本穩定性指標(Population Stability Index, PSI)檢驗模型 穩定性"}'::jsonb, array['L23-5.1']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 25, '114 年第 2 次中級第三科公告試題，第 25 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 25, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q26', 'L23', 'official', '在防止監督式學習模型過擬合(Overfitting)時,下列哪一種策略不屬於 降低模型複雜度或限制學習能力的作法?', '{"A":"採用 L1 或 L2 正則化;","B":"在訓練過程中使用 Dropout 技術;","C":"採取早期停止(Early Stopping)機制;","D":"擴增輸入特徵變數以提升模型表達能力"}'::jsonb, array['L23-5.4']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 26, '114 年第 2 次中級第三科公告試題，第 26 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 26, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q27', 'L23', 'official', '某智慧製造團隊在開發瑕疵影像檢測模型時,發現使用線性激活函數 (Activation Function)後,模型的訓練準確率長期停滯,懷疑模型無法 學習到足夠複雜的特徵表達。若要改善此問題,下列哪一項調整方案最為 合適?', '{"A":"增加卷積層(Convolutional Layer)數量,使網路更深以強化特徵提 取;","B":"將輸入影像先進行灰階化處理,降低運算量;","C":"使用 Sigmoid 激活函數,以將輸出壓縮至[0,1]範圍;","D":"改用 ReLU(Rectified Linear Unit)激活函數,以引入非線性並提升 模型表達能力"}'::jsonb, array['L23-5.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 27, '114 年第 2 次中級第三科公告試題，第 27 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 27, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q28', 'L23', 'official', '一家零售電商公司希望建立顧客流失預測模型,用以判斷哪些會員可能在 三個月內不再消費。團隊以去年會員資料進行訓練,並僅採用「曾經購買 三次以上」的活躍顧客紀錄作為樣本。模型上線後,對整體會員進行預測 時,發現模型對於新註冊會員與低消費會員的預測準確率明顯偏低。下列 何者為造成此現象最可能的原因?', '{"A":"特徵設計未排除與會員忠誠度高度相關的變數,導致特徵偏差 (Feature Bias);","B":"標記(Label)由人工標註,導致標籤偏差(Label Bias);","C":"訓練樣本僅涵蓋高活躍顧客,造成取樣偏差(Sampling Bias);","D":"模型未進行超參數調整,導致過擬合(Overfitting)"}'::jsonb, array['L23-6.2']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 28, '114 年第 2 次中級第三科公告試題，第 28 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 28, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q29', 'L23', 'official', '在工業設備故障預測專案中,模型訓練與超參數調整均依賴於一段歷史數 據作為驗證集。然而,隨著設備運行環境與工況條件的變化,原有驗證集 已無法充分反映現況,導致模型在實際部署後的預測準確率逐漸下降。下 列哪一種策略最能有效提升模型在長期運行環境中的穩健性與泛化能力?', '{"A":"固定驗證集內容,並透過模型正則化技巧(如 L2 正則化)強化模型泛 化;","B":"將全部歷史資料納入訓練,不使用驗證集,依靠早期停止(Early Stopping)控制訓練;","C":"簡化模型架構,減少模型參數數量以降低過擬合風險;","D":"採用時間序列交叉驗證(Time Series Cross Validation)或滑動視窗 驗證(Rolling Window Validation)方法,動態更新驗證資料以適應時間 演進"}'::jsonb, array['L23-5.4']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 29, '114 年第 2 次中級第三科公告試題，第 29 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 29, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q30', 'L23', 'official', '某情感分析模型在英文資料集上取得 macro F1-score = 0.91。當該模型 部署於西班牙文資料集時,F1-score 驟降至 0.58。下列哪一項解釋最合 理,且與 F1-score 變化相關?', '{"A":"macro F1-score 本身波動性高,建議改用 micro-average F1-score 評估;","B":"模型在西班牙文語料上過度擬合,導致評估結果偏高;","C":"語言轉移造成召回率(Recall)下降,模型無法正確辨識關鍵情緒詞 彙;","D":"以均方誤差(MSE)取代 F1-score 評估可獲得更準確的結果"}'::jsonb, array['L23-5.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 30, '114 年第 2 次中級第三科公告試題，第 30 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 30, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q31', 'L23', 'official', '某能源公司利用歷史氣象與用電資料,開發長期電力需求預測模型,採用 深度神經網路架構進行訓練。在訓練過程中,模型在訓練集上的損失值持 續下降,但在驗證集上,損失在第 80 輪後開始波動,呈現週期性上升與下 降。團隊懷疑模型受到季節性資料波動與隨機噪音影響,導致驗證損失難 以穩定收斂。若要在此情境下合理運用早期停止法(Early Stopping)以 確保模型具最佳泛化能力,下列哪一項策略最為適當?', '{"A":"直接根據訓練集損失最低點停止訓練,以確保模型充分擬合所有樣本;","B":"監控驗證集損失並設定適度的耐心值(Patience) ,在連續多輪未改善 後再停止訓練;","C":"改以測試集損失作為早停依據,以提升模型最終評估一致性;","D":"將所有資料重新合併後訓練至收斂,避免因資料分割導致評估波動"}'::jsonb, array['L23-5.4']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 31, '114 年第 2 次中級第三科公告試題，第 31 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 31, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q32', 'L23', 'official', '某電信公司開發客戶流失預測模型,使用大量顧客行為特徵,例如通話時 長、上網頻率、帳單金額、客服聯絡次數等。在訓練過程中,團隊發現部 分特徵彼此高度相關,但同時也懷疑有些特徵對流失預測的貢獻度有限。 若希望模型在避免過擬合(Overfitting)的同時,能自動篩選出較具代表 性的特徵,採用下列哪一種方法最為合適?', '{"A":"使用早期停止法(Early Stopping)控制訓練回合數,避免過擬合 (Overfitting);","B":"同時移除多重共線性特徵並採用 L2 正則化(Ridge) ,以確保模型穩定 收斂;","C":"僅使用 L2 正則化(Ridge) ,抑制所有權重幅度但保留全部特徵;","D":"採用 L1 正則化(Lasso) ,透過懲罰項使部分特徵係數縮為0"}'::jsonb, array['L23-5.4']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 32, '114 年第 2 次中級第三科公告試題，第 32 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 32, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q33', 'L23', 'official', '某資料科學團隊正在開發一個客戶相似度比對系統,用於計算所有客戶之 間的相似度分數。若系統需逐一比對每一位客戶與其他所有客戶的資料組 合,此時演算法的時間複雜度最可能為哪一種?其代表意義為何?', '{"A":"O(n) — 執行時間與資料量成線性關係;","B":"O(n2) — 執行時間與資料量平方成正比;","C":"O(1) — 執行時間固定不變;","D":"O(log n) — 執行時間與資料量呈對數成長關係"}'::jsonb, array['L23-4.1']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 33, '114 年第 2 次中級第三科公告試題，第 33 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 33, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q34', 'L23', 'official', '某醫療人工智慧團隊正在開發心臟病風險預測模型,資料量僅有 150 筆, 其中陽性個案不到 8%。由於樣本數稀少且類別分布極不平衡,團隊希望在 有限資料下,仍能準確評估模型在不同資料上的表現穩定性,同時避免訓 練資料被過度切分而影響模型效能。若團隊希望在有限樣本下,同時兼顧 資料的利用率與各類別在驗證折中的比例一致性,最適合採用下列哪一種 交叉驗證方法?', '{"A":"5-Fold 交叉驗證(5-Fold Cross Validation);","B":"留一法交叉驗證(Leave-One-Out Cross Validation);","C":"隨機交叉驗證(Random Cross Validation);","D":"分層留一法交叉驗證(Stratified Leave-One-Out Cross Validation)"}'::jsonb, array['L23-5.3']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 34, '114 年第 2 次中級第三科公告試題，第 34 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 34, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q35', 'L23', 'official', '某公司針對製程感測器資料進行主成分分析(PCA) ,經標準化與協方差矩 陣分解後,得到三個主成分的特徵值如下:λ1=6.0, λ2=3.0, λ3=1.0。 若團隊決定僅保留能解釋至少 80% 總變異量的主成分,以進行後續模型建 構,下列哪一項敘述最合理且數據解讀正確?', '{"A":"前兩個主成分合計解釋 90%的總變異量,因此可安全降維至二維,且仍 保留大部分資訊;","B":"第一主成分解釋 60%的變異量,表示資料結構呈現明顯線性關係,僅保 留一維即可避免過擬合;","C":"雖然前兩個主成分可解釋超過 80% 變異量,但第二主成分貢獻仍高達 30%,不宜捨棄第三主成分;","D":"三個特徵值相差不大,顯示各主成分變異均衡,降維可能導致資訊損失"}'::jsonb, array['L23-6.1']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 35, '114 年第 2 次中級第三科公告試題，第 35 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 35, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q36', 'L23', 'official', '某銀行計畫與多家合作機構共同訓練一個 AI 信用風險預測模型,為避免客 戶交易資料在傳輸與運算過程中外洩,技術團隊評估使用同態加密 (Homomorphic Encryption)技術。下列何者最能正確描述同態加密在此 應用中的關鍵特性?', '{"A":"系統以隨機雜訊(Noise)干擾輸出,確保統計結果不洩漏個資;","B":"各參與銀行透過安全通道交換私鑰,確保模型參數一致;","C":"將原始資料壓縮並同時加密,以減少加密後資料量與運算時間;","D":"資料在加密狀態下仍可進行數值運算,模型訓練可於未解密資料上完成"}'::jsonb, array['L23-6.1']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 36, '114 年第 2 次中級第三科公告試題，第 36 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 36, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q37', 'L23', 'official', '某跨銀行風控平台希望整合多家銀行的用戶行為資料,用於訓練信用風險 預測模型。由於競爭與法規限制,各銀行僅願意提供加密後資料,且資料 在任何時間不得被平台解密。同時,平台需建立安全通訊協議以確保資料 在傳輸過程未被竄改或重放。 下列哪一組技術最能完整對應上述需求?', '{"A":"對稱加密(Symmetric Encryption)+ 單向雜湊(Hash Function)+ 非對稱加密(Asymmetric Encryption)+ 差分隱私(Differential Privacy);","B":"同態加密(Homomorphic Encryption)+ 非對稱加密(Asymmetric Encryption)+ 單向雜湊( One-way Hash Function)+ 對稱加密","C":"差分隱私(Differential Privacy)+ 對稱加密(Symmetric Encryption)+ 同態加密(Homomorphic Encryption)+ 數位簽章 (Digital Signature);","D":"同態加密(Homomorphic Encryption)+ 安全多方計算(Secure Multi-party Computation, MPC)+ 雜湊函數(Hash Function)+ 對稱 加密(Symmetric Encryption)"}'::jsonb, array['L23-6.1']::text[], 2, array['歷屆試題', '114年第2次']::text[], null, 37, '114 年第 2 次中級第三科公告試題，第 37 題', 'https://www.ipas.org.tw/DownloadFile.ashx?filename=cb3be209-2b21-4e48-8e2f-8644fce7ba2a_114%E5%B9%B4%E7%AC%AC%E4%BA%8C%E6%AC%A1%E4%B8%AD%E7%B4%9AAI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB_%E7%AC%AC%E4%B8%89%E7%A7%91_%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8%28%E7%95%B6%E6%AC%A1%E8%A9%A6%E9%A1%8C%E5%85%AC%E5%91%8A114.11.20%29.pdf&type=10', 114, '2', 37, null, null, '[{"title":"iPAS L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-114-S2-Q38', 'L23', 'official', '附圖程式碼計算的評估指標是哪一種？

