  ('L23-AUTO-exam_style-047', 'L23', 'exam_style', '仿歷屆情境題：聯邦學習中，典型做法如何減少原始資料集中傳輸？', '{"A":"原始資料留在本地並交換模型更新","B":"移除訓練資料","C":"上傳所有原始資料","D":"公開全部使用者標籤"}'::jsonb, array['L23-6.1']::text[], 2, array['自編題', '仿歷屆題型']::text[], null, 47, '自編題：仿歷屆題型', null, null, null, null, null, 'iPAS 歷屆單選題型', '[{"title":"一手理論或官方技術資料","url":"https://arxiv.org/abs/1602.05629"},{"title":"iPAS 中級 L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-AUTO-exam_style-048', 'L23', 'exam_style', '仿歷屆情境題：差分隱私的 epsilon 越小通常有何取捨？', '{"A":"保證模型無偏","B":"隱私保護較強、效用可能下降","C":"隱私保護較弱而更準確","D":"完全不需雜訊"}'::jsonb, array['L23-6.1']::text[], 2, array['自編題', '仿歷屆題型']::text[], null, 48, '自編題：仿歷屆題型', null, null, null, null, null, 'iPAS 歷屆單選題型', '[{"title":"一手理論或官方技術資料","url":"https://www.cis.upenn.edu/~aaroth/Papers/privacybook.pdf"},{"title":"iPAS 中級 L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-AUTO-guide_research-047', 'L23', 'guide_research', '若分類器對各群體校準良好，相同預測機率應如何解讀？', '{"A":"各群體實際事件比例大致相符","B":"各群體正向預測比例必定相同","C":"模型必定沒有偏差","D":"所有群體錯誤率必定相同"}'::jsonb, array['L23-6.2']::text[], 2, array['自編題', '學習指引理論研究']::text[], null, 47, '自編題：依學習指引章節與理論來源設計', null, null, null, null, null, null, '[{"title":"iPAS AI 應用規劃師中級學習指引，科目三：機器學習技術與應用","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"},{"title":"Primary theory reference","url":"https://arxiv.org/abs/1609.05807"}]'::jsonb, '2026-09-29', false),
  ('L23-AUTO-guide_research-048', 'L23', 'guide_research', '只公布全體準確率作為公平性結論，主要限制為何？', '{"A":"必然高估少數群體表現","B":"可能掩蓋不同群體的錯誤率差異","C":"能證明所有群體結果一致","D":"可取代資料代表性檢查"}'::jsonb, array['L23-6.2']::text[], 2, array['自編題', '學習指引理論研究']::text[], null, 48, '自編題：依學習指引章節與理論來源設計', null, null, null, null, null, null, '[{"title":"iPAS AI 應用規劃師中級學習指引，科目三：機器學習技術與應用","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"},{"title":"Primary theory reference","url":"https://airc.nist.gov/airmf-resources/airmf/5-sec-core/"}]'::jsonb, '2026-09-29', false),
  ('L23-AUTO-exam_style-049', 'L23', 'exam_style', '仿歷屆情境題：依 NIST AI RMF 評估模型公平與偏差，合理做法為何？', '{"A":"只報整體 accuracy","B":"不需記錄結果","C":"依情境選定公平指標並記錄群體結果","D":"假設刪敏感欄即可消除偏差"}'::jsonb, array['L23-6.2']::text[], 2, array['自編題', '仿歷屆題型']::text[], null, 49, '自編題：仿歷屆題型', null, null, null, null, null, 'iPAS 歷屆單選題型', '[{"title":"一手理論或官方技術資料","url":"https://airc.nist.gov/airmf-resources/airmf/5-sec-core/"},{"title":"iPAS 中級 L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-AUTO-exam_style-050', 'L23', 'exam_style', '仿歷屆情境題：兩群體基準率不同時，多種公平條件之間可能如何？', '{"A":"所有指標必定相同","B":"刪掉群體欄就必定滿足","C":"模型準確率必為零","D":"某些準則無法同時滿足"}'::jsonb, array['L23-6.2']::text[], 2, array['自編題', '仿歷屆題型']::text[], null, 50, '自編題：仿歷屆題型', null, null, null, null, null, 'iPAS 歷屆單選題型', '[{"title":"一手理論或官方技術資料","url":"https://arxiv.org/abs/1609.05807"},{"title":"iPAS 中級 L23 學習指引","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"}]'::jsonb, '2026-09-29', false),
  ('L23-AUTO-guide_research-049', 'L23', 'guide_research', '訓練資料對某群體代表不足，合宜的第一步為何？', '{"A":"只刪敏感欄位便宣稱公平","B":"以模型參數數量判定偏差","C":"檢查資料收集、標籤與分群表現，再評估補足方式","D":"降低所有群體共用閾值"}'::jsonb, array['L23-6.2']::text[], 2, array['自編題', '學習指引理論研究']::text[], null, 49, '自編題：依學習指引章節與理論來源設計', null, null, null, null, null, null, '[{"title":"iPAS AI 應用規劃師中級學習指引，科目三：機器學習技術與應用","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"},{"title":"Primary theory reference","url":"https://airc.nist.gov/airmf-resources/airmf/5-sec-core/"}]'::jsonb, '2026-09-29', false),
  ('L23-AUTO-guide_research-050', 'L23', 'guide_research', '固定其他條件、改變敏感屬性後比較預測是否不合理改變，屬於哪種評估思路？', '{"A":"特徵重要度排序","B":"群內平方和","C":"資料標準化","D":"反事實公平性檢查"}'::jsonb, array['L23-6.2']::text[], 2, array['自編題', '學習指引理論研究']::text[], null, 50, '自編題：依學習指引章節與理論來源設計', null, null, null, null, null, null, '[{"title":"iPAS AI 應用規劃師中級學習指引，科目三：機器學習技術與應用","url":"https://www.ipas.org.tw/api/proxy/uploads/certification_resource/bf93f438f7be48d295c1b40a34d79f3d/AI%E6%87%89%E7%94%A8%E8%A6%8F%E5%8A%83%E5%B8%AB(%E4%B8%AD%E7%B4%9A)-%E5%AD%B8%E7%BF%92%E6%8C%87%E5%BC%95-%E7%A7%91%E7%9B%AE3%E6%A9%9F%E5%99%A8%E5%AD%B8%E7%BF%92%E6%8A%80%E8%A1%93%E8%88%87%E6%87%89%E7%94%A8_20251222101907.pdf"},{"title":"Primary theory reference","url":"https://arxiv.org/abs/1703.06856"}]'::jsonb, '2026-09-29', false)
